interface LoadedFile {
  fileId: string;
  root: THREE.Object3D;
  mixer: THREE.AnimationMixer;
  clipsByName: Map<string, THREE.AnimationClip>;
  morphMeshes: { mesh: THREE.Mesh; bindings: Record<string, MorphTargetBinding[]> }[];
  availableMorphTargets: string[];
  stats: {
    meshVertexCount: number;
    jointCount: number;
    animationCount: number;
  };
  /** 浏览器侧创建的 ObjectURL（如有），dispose 时需 revoke */
  objectUrl: string | null;
}

export interface PlayClipOptions {
  loop?: boolean;
  timeScale?: number;
}

export interface ClipDescriptor {
  name: string;
  duration: number;
}

export interface LoadResult {
  clips: ClipDescriptor[];
  availableMorphTargets: string[];
  stats: {
    meshVertexCount: number;
    jointCount: number;
    animationCount: number;
  };
}

export type MergeClipFailCode =
  | 'source_or_target_not_loaded'
  | 'source_clip_not_found'
  | 'empty_merged_name'
  | 'merged_name_conflict'
  | 'track_parse_failed'
  | 'strict_node_mapping_failed'
  | 'no_compatible_tracks';

export interface MergeClipResult {
  ok: boolean;
  code?: MergeClipFailCode;
  missingNodeMappings: string[];
  droppedTrackCount: number;
  droppedBoneScaleTrackCount: number;
  mergedTrackCount: number;
  parseFailedTrackName?: string;
}


export type LightingPreset = 'threePoint' | 'butterfly' | 'rembrandt' | 'split' | 'ring';

