function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

function clampCameraFov(value: number): number {
  return Math.min(MAX_CAMERA_FOV, Math.max(MIN_CAMERA_FOV, value));
}

function isHdrTextureFile(file: File): boolean {
  return file.name.toLowerCase().endsWith('.hdr') || file.type === 'image/vnd.radiance';
}

async function loadHdriTexture(objectUrl: string, file: File): Promise<THREE.Texture> {
  if (isHdrTextureFile(file)) {
    return new Promise<THREE.DataTexture>((resolve, reject) => {
      const loader = new RGBELoader();
      loader.load(
        objectUrl,
        (texture) => {
          const nextTexture = texture;
          nextTexture.mapping = THREE.EquirectangularReflectionMapping;
          nextTexture.magFilter = THREE.LinearFilter;
          nextTexture.minFilter = THREE.LinearFilter;
          nextTexture.generateMipmaps = false;
          resolve(nextTexture);
        },
        undefined,
        reject,
      );
    });
  }

  return new Promise<THREE.Texture>((resolve, reject) => {
    const loader = new THREE.TextureLoader();
    loader.load(
      objectUrl,
      (texture) => {
        const nextTexture = texture;
        nextTexture.mapping = THREE.EquirectangularReflectionMapping;
        resolve(nextTexture);
      },
      undefined,
      reject,
    );
  });
}

function cloneLightingSettings(settings: PreviewLightingSettings): PreviewLightingSettings {
  return {
    preset: settings.preset,
    base: {
      enabled: settings.base.enabled,
      showMarkers: settings.base.showMarkers,
      colors: {
        key: settings.base.colors.key,
        fill: settings.base.colors.fill,
        rim: settings.base.colors.rim,
      },
    },
    global: {
      ambientEnabled: settings.global.ambientEnabled,
      ambientColor: settings.global.ambientColor,
      ambientIntensity: settings.global.ambientIntensity,
      hdriEnabled: settings.global.hdriEnabled,
      hdriIntensity: settings.global.hdriIntensity,
      hdriShowBackground: settings.global.hdriShowBackground,
    },
  };
}

function applyColor(light: THREE.Light, value: string): void {
  try {
    light.color.set(value);
  } catch {
    light.color.set('#ffffff');
  }
}

function createLightMarker(initialColor: string): LightMarkerMesh {
  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.06, 16, 16),
    new THREE.MeshBasicMaterial({
      color: initialColor,
      transparent: true,
      opacity: 0.95,
      toneMapped: false,
      depthTest: false,
    }),
  );
  marker.renderOrder = 10;
  marker.visible = false;
  return marker;
}

function applyMarkerColor(marker: LightMarkerMesh | null, value: string): void {
  if (!marker) {
    return;
  }
  try {
    marker.material.color.set(value);
  } catch {
    marker.material.color.set('#ffffff');
  }
}

export function createDefaultPreviewLightingSettings(): PreviewLightingSettings {
  return cloneLightingSettings(DEFAULT_LIGHTING_SETTINGS);
}

interface ParsedTrackBinding {
  nodeName?: string;
  objectName?: string;
  objectIndex?: string | number;
  propertyName?: string;
  propertyIndex?: string | number;
}

function extractTrackNodeToken(name: string): string {
  const trimmed = name.trim().replace(/^['"]|['"]$/g, '');
  const segments = trimmed.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? trimmed;
}

function normalizeNodeName(name: string | null | undefined): string {
  if (!name) {
    return '';
  }
  return extractTrackNodeToken(name).replace(/\.\d{3}$/, '');
}


function buildNodeCandidates(root: THREE.Object3D): Map<string, THREE.Object3D[]> {
  const candidates = new Map<string, THREE.Object3D[]>();
  root.traverse((node) => {
    const normalizedName = normalizeNodeName(node.name);
    if (!normalizedName) {
      return;
    }
    const list = candidates.get(normalizedName) ?? [];
    list.push(node);
    candidates.set(normalizedName, list);
  });
  return candidates;
}

function collectPreferredNodes(root: THREE.Object3D): Set<string> {
  const preferred = new Set<string>();
  root.traverse((node) => {
    if (!(node as THREE.SkinnedMesh).isSkinnedMesh) {
      return;
    }
    const mesh = node as THREE.SkinnedMesh;
    mesh.skeleton?.bones.forEach((bone) => preferred.add(bone.uuid));
  });
  return preferred;
}

function chooseTargetNode(candidates: THREE.Object3D[], preferredNodes: Set<string>): THREE.Object3D {
  const preferred = candidates.find((node) => preferredNodes.has(node.uuid));
  if (preferred) {
    return preferred;
  }
  return candidates[candidates.length - 1] as THREE.Object3D;
}

function buildTrackName(parsed: ParsedTrackBinding, nextNodeToken: string, fallbackName: string): string {
  if (!parsed.propertyName) {
    return fallbackName;
  }

  let nextName = nextNodeToken;
  if (parsed.objectName) {
    nextName += `.${parsed.objectName}`;
    if (parsed.objectIndex !== undefined) {
      nextName += `[${parsed.objectIndex}]`;
    }
  }

  nextName += `.${parsed.propertyName}`;
  if (parsed.propertyIndex !== undefined) {
    nextName += `[${parsed.propertyIndex}]`;
  }

  return nextName;
}


export class ThreePreview {

  private renderer: THREE.WebGLRenderer | null = null;

  private scene: THREE.Scene | null = null;

  private camera: THREE.PerspectiveCamera | null = null;

  private controls: OrbitControls | null = null;

  private clock = new THREE.Clock();

  private rafId: number | null = null;

  private resizeObserver: ResizeObserver | null = null;

  private gltfLoader: GLTFLoader | null = null;

  private dracoLoader: DRACOLoader | null = null;

  private loadedFiles = new Map<string, LoadedFile>();

  private activeFileId: string | null = null;

  private currentAction: THREE.AnimationAction | null = null;

  private mountedRoot: THREE.Object3D | null = null;

  private ambientLight: THREE.AmbientLight | null = null;

  private keyLight: THREE.DirectionalLight | null = null;

  private fillLight: THREE.DirectionalLight | null = null;

  private rimLight: THREE.DirectionalLight | null = null;

  private keyLightMarker: LightMarkerMesh | null = null;

  private fillLightMarker: LightMarkerMesh | null = null;

  private rimLightMarker: LightMarkerMesh | null = null;

  private pmremGenerator: THREE.PMREMGenerator | null = null;


  private hdriTarget: THREE.WebGLRenderTarget | null = null;

  private hdriSourceTexture: THREE.Texture | null = null;

  private lightingSettings: PreviewLightingSettings = createDefaultPreviewLightingSettings();

  private cameraFov = DEFAULT_CAMERA_FOV;

  /**
   * 用于 setMorphWeights 时的兜底：未提供权重的 morph target 默认归零，
   * 避免上一组动画的状态泄漏到下一组。
   */
  private lastWeights: Record<string, number> = {};

  /**
   * 把 renderer/scene/camera/controls 挂到指定 canvas。幂等：重复调用同一 canvas 不会重建。
   */
  mount(canvas: HTMLCanvasElement): void {
    if (this.renderer?.domElement === canvas) {
      return;
    }
    if (this.renderer) {
      this.dispose();
    }

    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;

    const scene = new THREE.Scene();
    scene.background = null;

    const camera = new THREE.PerspectiveCamera(this.cameraFov, 1, 0.01, 100);
    camera.position.set(0, 1.4, 2.6);
    camera.lookAt(0, 1.0, 0);

    const ambient = new THREE.AmbientLight(0xffffff, 0.35);
    const key = new THREE.DirectionalLight(0xfffaf0, 1.9);
    const fill = new THREE.DirectionalLight(0xcfe8ff, 0.95);
    const rim = new THREE.DirectionalLight(0xffffff, 1.1);
    const keyLightMarker = createLightMarker('#fffaf0');
    const fillLightMarker = createLightMarker('#cfe8ff');
    const rimLightMarker = createLightMarker('#ffffff');
    scene.add(ambient, key, fill, rim, keyLightMarker, fillLightMarker, rimLightMarker);


    const grid = new THREE.GridHelper(4, 16, 0x4b5563, 0x1f2937);
    (grid.material as THREE.Material).transparent = true;
    (grid.material as THREE.Material).opacity = 0.5;
    scene.add(grid);

    const controls = new OrbitControls(camera, canvas);
    controls.enableDamping = true;
    controls.target.set(0, 1.0, 0);
    controls.update();

    const dracoLoader = new DRACOLoader();
    dracoLoader.setDecoderPath(DEFAULT_DRACO_PATH);
    const gltfLoader = new GLTFLoader();
    gltfLoader.setDRACOLoader(dracoLoader);

    const pmremGenerator = new THREE.PMREMGenerator(renderer);

    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.controls = controls;
    this.dracoLoader = dracoLoader;
    this.gltfLoader = gltfLoader;
    this.ambientLight = ambient;
    this.keyLight = key;
    this.fillLight = fill;
    this.rimLight = rim;
    this.keyLightMarker = keyLightMarker;
    this.fillLightMarker = fillLightMarker;
    this.rimLightMarker = rimLightMarker;
    this.pmremGenerator = pmremGenerator;


    this.setLightingSettings(this.lightingSettings);
    this.setCameraFov(this.cameraFov);
    this.attachResize(canvas);
    this.startLoop();
  }

  hasHdriTexture(): boolean {
    return Boolean(this.hdriTarget);
  }

  setCameraFov(nextFov: number): void {
    const safeFov = clampCameraFov(nextFov);
    this.cameraFov = safeFov;

    if (!this.camera) {
      return;
    }

    this.camera.fov = safeFov;
    this.camera.updateProjectionMatrix();
  }

  async setHdriTextureFile(file: File | null): Promise<boolean> {
    if (!this.renderer || !this.pmremGenerator) {
      return false;
    }

    if (!file) {
      this.disposeHdrTexture();
      this.setLightingSettings({
        ...this.lightingSettings,
        global: {
          ...this.lightingSettings.global,
          hdriEnabled: false,
        },
      });
      return false;
    }

    const objectUrl = URL.createObjectURL(file);

    try {
      const texture = await loadHdriTexture(objectUrl, file);

      this.disposeHdrTexture();
      this.hdriSourceTexture = texture;
      this.hdriTarget = this.pmremGenerator.fromEquirectangular(texture);
      this.setLightingSettings(this.lightingSettings);
      return true;
    } catch (error) {
      logger.warn('three-preview', 'load hdri texture failed', { error: String(error) });
      return false;
    } finally {
      URL.revokeObjectURL(objectUrl);
    }
  }

  /** 预览窗口人物照明设置（基础布光 + 漫反射光 + HDRI） */
  setLightingSettings(nextSettings: PreviewLightingSettings): void {
    this.lightingSettings = cloneLightingSettings(nextSettings);

    const { keyLight } = this;
    const { fillLight } = this;
    const { rimLight } = this;
    const { ambientLight } = this;

    if (!keyLight || !fillLight || !rimLight || !ambientLight) {
      return;
    }

    const preset = PRESET_LIGHT_LAYOUT[this.lightingSettings.preset];
    const baseLightsEnabled = this.lightingSettings.base.enabled;

    keyLight.position.set(...preset.key.position);
    keyLight.visible = baseLightsEnabled;
    keyLight.intensity = baseLightsEnabled ? preset.key.intensity : 0;

    fillLight.position.set(...preset.fill.position);
    fillLight.visible = baseLightsEnabled;
    fillLight.intensity = baseLightsEnabled ? preset.fill.intensity : 0;

    rimLight.position.set(...preset.rim.position);
    rimLight.visible = baseLightsEnabled;
    rimLight.intensity = baseLightsEnabled ? preset.rim.intensity : 0;

    applyColor(keyLight, this.lightingSettings.base.colors.key);
    applyColor(fillLight, this.lightingSettings.base.colors.fill);
    applyColor(rimLight, this.lightingSettings.base.colors.rim);

    const {ambientEnabled} = this.lightingSettings.global;
    applyColor(ambientLight, this.lightingSettings.global.ambientColor);
    ambientLight.visible = ambientEnabled;
    ambientLight.intensity = ambientEnabled ? clamp01(this.lightingSettings.global.ambientIntensity) : 0;

    this.keyLightMarker?.position.set(...preset.key.position);
    this.fillLightMarker?.position.set(...preset.fill.position);
    this.rimLightMarker?.position.set(...preset.rim.position);
    applyMarkerColor(this.keyLightMarker, this.lightingSettings.base.colors.key);
    applyMarkerColor(this.fillLightMarker, this.lightingSettings.base.colors.fill);
    applyMarkerColor(this.rimLightMarker, this.lightingSettings.base.colors.rim);
    if (this.keyLightMarker) {
      this.keyLightMarker.visible = this.lightingSettings.base.showMarkers;
    }
    if (this.fillLightMarker) {
      this.fillLightMarker.visible = this.lightingSettings.base.showMarkers;
    }
    if (this.rimLightMarker) {
      this.rimLightMarker.visible = this.lightingSettings.base.showMarkers;
    }

    if (this.scene) {
      const hdriReady = Boolean(this.hdriTarget && this.hdriSourceTexture);
      const hdriEnabled = this.lightingSettings.global.hdriEnabled && hdriReady;
      const showHdriBackground = hdriEnabled && this.lightingSettings.global.hdriShowBackground;
      this.scene.environment = hdriEnabled ? this.hdriTarget?.texture ?? null : null;
      this.scene.background = showHdriBackground ? this.hdriSourceTexture ?? null : null;
      const hdriIntensity = Math.max(0, this.lightingSettings.global.hdriIntensity);
      const sceneWithExt = this.scene as THREE.Scene & { environmentIntensity?: number };
      sceneWithExt.environmentIntensity = hdriEnabled ? hdriIntensity : 0;
    }
  }


  /**
   * 解析 ArrayBuffer 为 GLTF。three 的 GLTFLoader.parse 是同步式回调，这里包成 Promise。
   * 注意：parse 第二个参数是 path，传 '' 即可（无外部资源依赖）。
   */
  async load(buffer: ArrayBuffer, fileId: string): Promise<LoadResult> {
    this.ensureLoaders();

    if (this.loadedFiles.has(fileId)) {

      this.activate(fileId);
      const cached = this.loadedFiles.get(fileId);
      return cached
        ? this.toLoadResult(cached)
        : {
            clips: [],
            availableMorphTargets: [],
            stats: { meshVertexCount: 0, jointCount: 0, animationCount: 0 },
          };
    }

    const gltf = await new Promise<GLTF>((resolve, reject) => {
      this.gltfLoader!.parse(buffer, '', resolve, reject);
    });

    const root = gltf.scene ?? gltf.scenes[0];
    if (!root) {
      throw new Error('GLTF has no scene');
    }

    const mixer = new THREE.AnimationMixer(root);
    const clipsByName = new Map<string, THREE.AnimationClip>();
    for (const clip of gltf.animations) {
      clipsByName.set(clip.name, clip);
    }

    const morphMeshes: LoadedFile['morphMeshes'] = [];
    const availableMorphTargets = new Set<string>();
    let meshVertexCount = 0;
    let jointCount = 0;

    root.traverse((obj) => {
      if ((obj as THREE.SkinnedMesh).isSkinnedMesh) {
        const skinnedMesh = obj as THREE.SkinnedMesh;
        jointCount = Math.max(jointCount, skinnedMesh.skeleton?.bones.length ?? 0);
      }

      if ((obj as THREE.Mesh).isMesh) {
        const mesh = obj as THREE.Mesh;
        const positionAttribute = (mesh.geometry as THREE.BufferGeometry | undefined)?.getAttribute('position');
        if (positionAttribute) {
          meshVertexCount += positionAttribute.count;
        }

        if (mesh.morphTargetDictionary && mesh.morphTargetInfluences) {
          const bindings = buildMorphTargetBindings(mesh.morphTargetDictionary);
          for (const rawName of listMorphTargetNames(mesh.morphTargetDictionary)) {
            availableMorphTargets.add(rawName);
          }
          morphMeshes.push({ mesh, bindings });
        }
      }
    });

    root.visible = false;

    const file: LoadedFile = {
      fileId,
      root,
      mixer,
      clipsByName,
      morphMeshes,
      availableMorphTargets: Array.from(availableMorphTargets),
      stats: {
        meshVertexCount,
        jointCount,
        animationCount: clipsByName.size,
      },
      objectUrl: null,
    };
    this.loadedFiles.set(fileId, file);

    logger.info('three-preview', 'gltf loaded', {
      fileId,
      animations: clipsByName.size,
      morphMeshCount: morphMeshes.length,
      mounted: Boolean(this.scene),
    });

    this.activate(fileId);
    return this.toLoadResult(file);
  }


  /** 仅切换"当前显示文件"，不重新解析 */
  activate(fileId: string): void {
    const next = this.loadedFiles.get(fileId);

    if (!this.scene) {
      this.activeFileId = next ? fileId : null;
      this.currentAction = null;
      this.mountedRoot = null;
      return;
    }

    for (const [id, loaded] of this.loadedFiles.entries()) {

      const isActive = id === fileId;
      if (!isActive) {
        loaded.root.visible = false;
        loaded.mixer.stopAllAction();
      }
    }

    if (!next || !this.scene) {
      if (this.mountedRoot?.parent === this.scene) {
        this.scene?.remove(this.mountedRoot);
      }
      this.mountedRoot = null;
      this.activeFileId = null;
      this.currentAction = null;
      return;
    }

    if (this.mountedRoot && this.mountedRoot !== next.root && this.mountedRoot.parent === this.scene) {
      this.scene.remove(this.mountedRoot);
    }

    if (next.root.parent !== this.scene) {
      this.scene.add(next.root);
    }
    next.root.visible = true;

    if (this.activeFileId !== fileId) {
      this.currentAction = null;
    }
    this.activeFileId = fileId;
    this.mountedRoot = next.root;
  }

  mergeClipToFile(
    sourceFileId: string,
    sourceClipName: string,
    targetFileId: string,
    mergedClipName: string,
    options?: { force?: boolean },
  ): MergeClipResult {
    const source = this.loadedFiles.get(sourceFileId);
    const target = this.loadedFiles.get(targetFileId);

    const fail = (code: MergeClipFailCode, partial?: Partial<MergeClipResult>): MergeClipResult => ({
      ok: false,
      code,
      missingNodeMappings: partial?.missingNodeMappings ?? [],
      droppedTrackCount: partial?.droppedTrackCount ?? 0,
      droppedBoneScaleTrackCount: partial?.droppedBoneScaleTrackCount ?? 0,
      mergedTrackCount: partial?.mergedTrackCount ?? 0,
      parseFailedTrackName: partial?.parseFailedTrackName,
    });

    if (!source || !target) {
      logger.warn('three-preview', 'mergeClipToFile skipped: source/target not loaded', {
        sourceFileId,
        targetFileId,
      });
      return fail('source_or_target_not_loaded');
    }

    const sourceClip = this.resolveClip(source, sourceClipName);
    if (!sourceClip) {
      logger.warn('three-preview', 'mergeClipToFile skipped: source clip not found', {
        sourceFileId,
        sourceClipName,
        targetFileId,
      });
      return fail('source_clip_not_found');
    }

    const normalizedMergedName = mergedClipName.trim();
    if (!normalizedMergedName) {
      logger.warn('three-preview', 'mergeClipToFile skipped: empty merged name', {
        sourceFileId,
        sourceClipName,
        targetFileId,
      });
      return fail('empty_merged_name');
    }

    if (this.resolveClip(target, normalizedMergedName)) {
      logger.warn('three-preview', 'mergeClipToFile skipped: merged name conflict in target', {
        targetFileId,
        mergedClipName: normalizedMergedName,
      });
      return fail('merged_name_conflict');
    }

    const forceMerge = Boolean(options?.force);
    const targetNodeCandidates = buildNodeCandidates(target.root);
    const preferredTargetNodes = collectPreferredNodes(target.root);

    const remappedTracks: THREE.KeyframeTrack[] = [];
    const missingNodeMappings = new Set<string>();
    const droppedBoneScaleTrackCount = 0;
    let droppedTrackCount = 0;
    let parsedByNodePathCount = 0;
    let parsedByNodeTokenCount = 0;
    let preferredNodeHitCount = 0;

    for (const track of sourceClip.tracks) {
      try {
        const parsed = THREE.PropertyBinding.parseTrackName(track.name) as ParsedTrackBinding;
        if (!parsed.nodeName) {
          remappedTracks.push(track.clone());
          continue;
        }

        const parsedNodeToken = extractTrackNodeToken(parsed.nodeName);
        const sourceNodeByPath = THREE.PropertyBinding.findNode(source.root, parsed.nodeName) as THREE.Object3D | null;
        const sourceNodeByToken = sourceNodeByPath ? null : THREE.PropertyBinding.findNode(source.root, parsedNodeToken) as THREE.Object3D | null;
        const sourceNode = sourceNodeByPath ?? sourceNodeByToken;
        if (sourceNodeByPath) {
          parsedByNodePathCount += 1;
        } else if (sourceNodeByToken) {
          parsedByNodeTokenCount += 1;
        }

        const normalizedSourceNodeName = normalizeNodeName(sourceNode?.name ?? parsedNodeToken);
        const targetCandidates = targetNodeCandidates.get(normalizedSourceNodeName);
        if (!normalizedSourceNodeName || !targetCandidates?.length) {
          missingNodeMappings.add(normalizedSourceNodeName || parsedNodeToken || parsed.nodeName);
          droppedTrackCount += 1;
          continue;
        }

        const targetNode = chooseTargetNode(targetCandidates, preferredTargetNodes);
        if (preferredTargetNodes.has(targetNode.uuid)) {
          preferredNodeHitCount += 1;
        }

        // 对齐 py 脚本：scale 轨道不做额外过滤，按节点映射后完整保留。
        const remappedTrack = track.clone();
        remappedTrack.name = buildTrackName(parsed, targetNode.uuid, track.name);
        remappedTracks.push(remappedTrack);
      } catch (error) {

        logger.warn('three-preview', 'mergeClipToFile skipped: track parse failed', {
          sourceFileId,
          sourceClipName,
          targetFileId,
          trackName: track.name,
          error: String(error),
        });
        if (!forceMerge) {
          return fail('track_parse_failed', { parseFailedTrackName: track.name, droppedTrackCount, droppedBoneScaleTrackCount });
        }
        droppedTrackCount += 1;
      }
    }

    if (missingNodeMappings.size > 0 && !forceMerge) {
      logger.warn('three-preview', 'mergeClipToFile skipped: strict node mapping failed', {
        sourceFileId,
        sourceClipName,
        targetFileId,
        missingNodeMappings: Array.from(missingNodeMappings),
      });
      logger.info('three-preview', 'mergeClipToFile py-compare', {
        mode: 'strict_failed',
        sourceFileId,
        sourceClipName,
        targetFileId,
        sourceTrackCount: sourceClip.tracks.length,
        remappedTrackCount: remappedTracks.length,
        droppedTrackCount,
        droppedBoneScaleTrackCount,
        parsedByNodePathCount,
        parsedByNodeTokenCount,
        preferredNodeHitCount,
        missingNodeMappings: Array.from(missingNodeMappings),
      });
      return fail('strict_node_mapping_failed', {
        missingNodeMappings: Array.from(missingNodeMappings),
        droppedTrackCount,
        droppedBoneScaleTrackCount,
      });
    }


    if (!remappedTracks.length) {
      logger.warn('three-preview', 'mergeClipToFile skipped: no compatible tracks left after filtering', {
        sourceFileId,
        sourceClipName,
        targetFileId,
      });
      return fail('no_compatible_tracks', {
        missingNodeMappings: Array.from(missingNodeMappings),
        droppedTrackCount,
        droppedBoneScaleTrackCount,
      });
    }

    const mergedClip = new THREE.AnimationClip(
      normalizedMergedName,
      sourceClip.duration,
      remappedTracks,
      sourceClip.blendMode,
    );

    target.clipsByName.set(normalizedMergedName, mergedClip);
    target.stats.animationCount = target.clipsByName.size;

    logger.info('three-preview', 'mergeClipToFile success', {
      sourceFileId,
      sourceClipName,
      targetFileId,
      mergedClipName: normalizedMergedName,
      sourceTrackCount: sourceClip.tracks.length,
      mergedTrackCount: remappedTracks.length,
      droppedTrackCount,
      droppedBoneScaleTrackCount,
      forceMerge,
      missingNodeMappings: Array.from(missingNodeMappings),
      targetAnimationCount: target.stats.animationCount,
    });
    logger.info('three-preview', 'mergeClipToFile py-compare', {
      mode: forceMerge ? 'force_success' : 'strict_success',
      sourceFileId,
      sourceClipName,
      targetFileId,
      mergedClipName: normalizedMergedName,
      sourceTrackCount: sourceClip.tracks.length,
      remappedTrackCount: remappedTracks.length,
      droppedTrackCount,
      droppedBoneScaleTrackCount,
      parsedByNodePathCount,
      parsedByNodeTokenCount,
      preferredNodeHitCount,
      missingNodeMappings: Array.from(missingNodeMappings),
    });


    return {
      ok: true,
      missingNodeMappings: Array.from(missingNodeMappings),
      droppedTrackCount,
      droppedBoneScaleTrackCount,
      mergedTrackCount: remappedTracks.length,
    };
  }




  renameClip(fileId: string, currentClipName: string, nextClipName: string): boolean {
    const file = this.loadedFiles.get(fileId);
    if (!file) {
      return false;
    }

    const normalizedCurrent = currentClipName.trim();
    const normalizedNext = nextClipName.trim();
    if (!normalizedCurrent || !normalizedNext) {
      return false;
    }

    if (normalizedCurrent === normalizedNext) {
      return true;
    }

    const current = this.resolveClip(file, normalizedCurrent);
    if (!current) {
      return false;
    }

    if (this.resolveClip(file, normalizedNext)) {
      return false;
    }

    file.clipsByName.delete(current.name);
    current.name = normalizedNext;
    file.clipsByName.set(normalizedNext, current);
    return true;
  }

  removeClip(fileId: string, clipName: string): boolean {
    const file = this.loadedFiles.get(fileId);
    if (!file) {
      return false;
    }

    const normalizedName = clipName.trim();
    const clip = this.resolveClip(file, normalizedName);
    if (!clip) {
      return false;
    }

    file.clipsByName.delete(clip.name);
    file.mixer.uncacheClip(clip);

    if (this.currentAction?.getClip().name === clip.name) {
      this.currentAction.stop();
      this.currentAction = null;
    }

    file.stats.animationCount = file.clipsByName.size;
    return true;
  }

  async exportMergedModelBuffer(fileId: string, clipNames?: string[]): Promise<ArrayBuffer | null> {

    const file = this.loadedFiles.get(fileId);
    if (!file) {
      return null;
    }

    const exporter = new GLTFExporter();
    const allClips = clipNames?.length
      ? clipNames
          .map((name) => this.resolveClip(file, name))
          .filter((clip): clip is THREE.AnimationClip => Boolean(clip))
      : Array.from(file.clipsByName.values());

    if (!allClips.length) {
      logger.warn('three-preview', 'exportMergedModelBuffer fallback: no clips resolved, exporting mesh only', { fileId });
    }

    return new Promise<ArrayBuffer | null>((resolve, reject) => {
      exporter.parse(
        file.root,
        (result) => {
          if (result instanceof ArrayBuffer) {
            resolve(result);
            return;
          }
          reject(new Error('GLTFExporter did not return binary GLB output'));
        },
        (error) => reject(error),
        {
          binary: true,
          onlyVisible: false,
          animations: allClips,
          trs: false,
        },
      );
    });
  }

  playClip(clipName: string, options: PlayClipOptions = {}): void {

    const file = this.activeFileId ? this.loadedFiles.get(this.activeFileId) : null;
    if (!file) {
      logger.warn('three-preview', 'playClip skipped: no active loaded file', {
        activeFileId: this.activeFileId,
      });
      return;
    }

    const normalizedName = clipName.trim();
    const clip = this.resolveClip(file, clipName);

    if (!clip) {
      logger.warn('three-preview', 'playClip: clip not found', {
        clipName,
        normalizedName,
        activeFileId: file.fileId,
        available: Array.from(file.clipsByName.keys()),
      });
      return;
    }

    logger.info('three-preview', 'playClip start', {
      clipName,
      resolvedClipName: clip.name,
      activeFileId: file.fileId,
      options,
      hasCurrentAction: Boolean(this.currentAction),
      currentActionClip: this.currentAction?.getClip().name,
      currentActionTime: this.currentAction?.time,
      currentActionPaused: this.currentAction?.paused,
    });

    file.mixer.stopAllAction();

    const action = file.mixer.clipAction(clip);
    action.reset();
    action.paused = false;
    action.enabled = true;
    action.clampWhenFinished = options.loop === false;
    action.setEffectiveWeight(1);
    action.setLoop(options.loop === false ? THREE.LoopOnce : THREE.LoopRepeat, Infinity);
    action.timeScale = options.timeScale ?? 1.0;
    action.play();
    this.currentAction = action;

    logger.info('three-preview', 'playClip applied', {
      clipName: action.getClip().name,
      running: action.isRunning(),
      paused: action.paused,
      enabled: action.enabled,
      timeScale: action.getEffectiveTimeScale(),
      weight: action.getEffectiveWeight(),
      time: action.time,
    });
  }


  pause(): void {
    if (this.currentAction) {
      this.currentAction.paused = true;
    }
  }

  resume(): void {
    if (this.currentAction) {
      this.currentAction.paused = false;
    }
  }

  setTimeScale(scale: number): void {
    if (this.currentAction) {
      this.currentAction.timeScale = scale;
    }
  }

  setLoop(loop: boolean): void {
    if (!this.currentAction) {
      return;
    }
    this.currentAction.clampWhenFinished = !loop;
    this.currentAction.setLoop(loop ? THREE.LoopRepeat : THREE.LoopOnce, Infinity);
  }

  seek(time: number): void {

    if (this.currentAction) {
      this.currentAction.time = time;
    }
  }

  /**
   * 把 glTF 实际 morph target 权重写入到所有 morph 网格。
   * - 对于本次未提供的、上次提供过的 target：回零（防泄漏）。
   * - 仅命中已加载 target 名的绑定才写入；不存在的 target 静默跳过。
   */
  setMorphWeights(weights: Record<string, number>): void {
    const file = this.activeFileId ? this.loadedFiles.get(this.activeFileId) : null;
    if (!file) {
      return;
    }

    const merged: Record<string, number> = { ...this.lastWeights };
    Object.keys(merged).forEach((channel) => {
      merged[channel] = 0;
    });
    Object.assign(merged, weights);

    for (const { mesh, bindings } of file.morphMeshes) {
      const influences = mesh.morphTargetInfluences;
      if (!influences) {
        continue;
      }
      for (const channel of Object.keys(merged)) {
        const channelBindings = bindings[channel];
        if (!channelBindings?.length) {
          continue;
        }
        const weight = Math.min(1, Math.max(0, merged[channel] ?? 0));
        channelBindings.forEach((binding) => {
          influences[binding.index] = weight;
        });
      }
    }
    this.lastWeights = { ...weights };
  }

  resetMorphWeights(): void {
    this.setMorphWeights({});
  }

  unloadFile(fileId: string): void {
    const file = this.loadedFiles.get(fileId);
    if (!file) {
      return;
    }
    file.mixer.stopAllAction();
    file.mixer.uncacheRoot(file.root);
    if (this.scene) {
      this.scene.remove(file.root);
    }
    disposeObject3D(file.root);
    if (file.objectUrl) {
      URL.revokeObjectURL(file.objectUrl);
    }
    this.loadedFiles.delete(fileId);
    if (this.activeFileId === fileId) {
      this.activeFileId = null;
      this.currentAction = null;
    }
    if (this.mountedRoot === file.root) {
      this.mountedRoot = null;
    }
  }

  unmount(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;

    this.controls?.dispose();
    this.controls = null;

    this.disposeHdrTexture();
    this.disposeLightMarkers();
    this.pmremGenerator?.dispose();
    this.pmremGenerator = null;

    this.renderer?.dispose();
    this.renderer = null;
    this.scene = null;
    this.camera = null;
    this.ambientLight = null;
    this.keyLight = null;
    this.fillLight = null;
    this.rimLight = null;
    this.keyLightMarker = null;
    this.fillLightMarker = null;
    this.rimLightMarker = null;
    this.currentAction = null;
    this.mountedRoot = null;
    this.lastWeights = {};
  }

  dispose(): void {
    this.unmount();

    for (const id of Array.from(this.loadedFiles.keys())) {
      this.unloadFile(id);
    }

    this.dracoLoader?.dispose();
    this.dracoLoader = null;
    this.gltfLoader = null;
    this.activeFileId = null;
  }


  private ensureLoaders(): void {
    if (this.gltfLoader && this.dracoLoader) {
      return;
    }

    const dracoLoader = new DRACOLoader();
    dracoLoader.setDecoderPath(DEFAULT_DRACO_PATH);
    const gltfLoader = new GLTFLoader();
    gltfLoader.setDRACOLoader(dracoLoader);

    this.dracoLoader = dracoLoader;
    this.gltfLoader = gltfLoader;
  }

  private resolveClip(file: LoadedFile, clipName: string): THREE.AnimationClip | null {

    const normalizedName = clipName.trim();
    const exact = file.clipsByName.get(normalizedName) ?? file.clipsByName.get(clipName);
    if (exact) {
      return exact;
    }

    return Array.from(file.clipsByName.entries()).find(([name]) => name.trim() === normalizedName)?.[1] ?? null;
  }

  private disposeLightMarkers(): void {

    const markers = [this.keyLightMarker, this.fillLightMarker, this.rimLightMarker];
    markers.forEach((marker) => {
      if (!marker) {
        return;
      }
      marker.parent?.remove(marker);
      marker.geometry.dispose();
      marker.material.dispose();
    });
  }

  private disposeHdrTexture(): void {
    this.hdriTarget?.dispose();
    this.hdriTarget = null;
    this.hdriSourceTexture?.dispose();
    this.hdriSourceTexture = null;
    if (this.scene) {
      this.scene.environment = null;
      this.scene.background = null;
      const sceneWithExt = this.scene as THREE.Scene & { environmentIntensity?: number };
      sceneWithExt.environmentIntensity = 0;
    }
  }


  private attachResize(canvas: HTMLCanvasElement): void {
    if (typeof ResizeObserver === 'undefined') {
      return;
    }
    const observer = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) {
        return;
      }
      const { width, height } = entry.contentRect;
      this.resize(width, height);
    });
    observer.observe(canvas.parentElement ?? canvas);
    this.resizeObserver = observer;
    this.resize(canvas.clientWidth || 1, canvas.clientHeight || 1);
  }

  private resize(width: number, height: number): void {
    if (!this.renderer || !this.camera) {
      return;
    }
    this.renderer.setSize(width, height, false);
    this.camera.aspect = Math.max(width, 1) / Math.max(height, 1);
    this.camera.updateProjectionMatrix();
  }

  private startLoop(): void {
    if (this.rafId !== null) {
      return;
    }
    const tick = () => {
      this.rafId = requestAnimationFrame(tick);
      const delta = this.clock.getDelta();
      const file = this.activeFileId ? this.loadedFiles.get(this.activeFileId) : null;
      file?.mixer.update(delta);
      this.controls?.update();
      if (this.renderer && this.scene && this.camera) {
        this.renderer.render(this.scene, this.camera);
      }
    };
    this.rafId = requestAnimationFrame(tick);
  }

  private toLoadResult(file: LoadedFile): LoadResult {
    const clips: ClipDescriptor[] = [];
    file.clipsByName.forEach((clip, name) => {
      clips.push({ name, duration: clip.duration });
    });
    return {
      clips,
      availableMorphTargets: [...file.availableMorphTargets],
      stats: { ...file.stats },
    };
  }
}

function disposeObject3D(root: THREE.Object3D): void {
  root.traverse((obj) => {
    const mesh = obj as THREE.Mesh;
    if (mesh.geometry) {
      mesh.geometry.dispose();
    }
    const mat = (mesh as { material?: THREE.Material | THREE.Material[] }).material;
    if (Array.isArray(mat)) {
      mat.forEach(disposeMaterial);
    } else if (mat) {
      disposeMaterial(mat);
    }
  });
}

function disposeMaterial(material: THREE.Material): void {
  for (const value of Object.values(material)) {
    if (value && (value as THREE.Texture).isTexture) {
      (value as THREE.Texture).dispose();
    }
  }
  material.dispose();
}

/** 模块级单例：character-editor 全局共用一份预览管线 */
export const threePreview = new ThreePreview();
