export interface JointDiff {
  onlyInTarget: string[];
  onlyInSource: string[];
  common: string[];
}

export function diffJoints(targetJointNames: string[], sourceJointNames: string[]): JointDiff {
  const targetSet = new Set(targetJointNames);
  const sourceSet = new Set(sourceJointNames);

  return {
    onlyInTarget: targetJointNames.filter((name) => !sourceSet.has(name)),
    onlyInSource: sourceJointNames.filter((name) => !targetSet.has(name)),
    common: targetJointNames.filter((name) => sourceSet.has(name)),
  };
}

export function buildMergedName(baseName: string, existingNames: Set<string>): string {
  if (!existingNames.has(baseName)) {
    return baseName;
  }

  let index = 1;
  while (existingNames.has(`${baseName}_merged_${index}`)) {
    index += 1;
  }

  return `${baseName}_merged_${index}`;
}
