<template>
  <div class="flex h-full min-h-0 flex-col">
    <p class="text-xs font-semibold uppercase tracking-wide text-slate-400">文件列表</p>
    <div class="mt-2 min-h-0 flex-1 space-y-2 overflow-auto pr-1">
      <button
        v-for="file in projectStore.files"
        :key="file.id"
        class="w-full rounded-md border px-2 py-2 text-left transition"
        :class="
          file.id === projectStore.activeFileId
            ? 'border-blue-500 bg-blue-500/20'
            : 'border-slate-700 bg-slate-800 hover:bg-slate-700/80'
        "
        type="button"
        @click="setActive(file.id)"
      >
        <div class="flex items-center justify-between gap-2">
          <p class="truncate text-xs text-slate-100">{{ file.name }}</p>
          <div class="flex items-center gap-1">
            <button
              class="rounded px-1.5 py-0.5 text-[10px]"
              :class="
                file.id === projectStore.targetFileId
                  ? 'bg-amber-400/20 text-amber-300'
                  : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
              "
              type="button"
              title="设为目标模型"
              @click.stop="setTarget(file.id)"
            >
              ★
            </button>
            <button
              class="rounded bg-rose-500/20 px-2 py-0.5 text-[10px] font-medium text-rose-300 hover:bg-rose-500/30"
              type="button"
              title="删除文件"
              @click.stop="openRemoveFileDialog(file.id)"
            >
              删除
            </button>
          </div>
        </div>
        <p class="mt-1 text-[11px] text-slate-400">
          {{ (file.size / 1024 / 1024).toFixed(2) }} MB · {{ file.animationCount }} clips
        </p>
      </button>
    </div>

    <div
      v-if="removeFileDialog.visible"
      class="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/70 px-4"
      data-testid="remove-file-dialog"
    >
      <div class="w-full max-w-md rounded-lg border border-rose-500/60 bg-slate-900 p-4 shadow-xl">
        <p class="text-sm font-semibold text-rose-200">确认删除模型</p>
        <p class="mt-2 text-xs text-slate-300">
          确认删除“{{ removeFileDialog.fileName }}”吗？该操作不可撤销。
        </p>
        <div class="mt-4 flex items-center justify-end gap-2">
          <button
            type="button"
            class="rounded border border-slate-600 px-3 py-1.5 text-xs text-slate-300 hover:bg-slate-800"
            @click="closeRemoveFileDialog"
          >
            取消
          </button>
          <button
            data-testid="confirm-remove-file-btn"
            type="button"
            class="rounded border border-rose-500 px-3 py-1.5 text-xs text-rose-200 hover:bg-rose-500/20"
            @click="confirmRemoveFile"
          >
            确认删除
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue';

import { logger } from '../services/logger';
import { threePreview } from '../services/three-preview';
import { useClipsStore } from '../stores/clips';
import { useProjectStore } from '../stores/project';

const projectStore = useProjectStore();
const clipsStore = useClipsStore();
const removeFileDialog = ref({
  visible: false,
  fileId: '',
  fileName: '',
});

function setActive(id: string) {
  projectStore.setActive(id);
  const file = projectStore.files.find((item) => item.id === id);
  if (!file?.arrayBuffer) {
    return;
  }
  threePreview
    .load(file.arrayBuffer, file.id)
    .then((loadResult) => {
      const hasAny = clipsStore.clips.some((clip) => clip.fileId === file.id);
      if (!hasAny) {
        clipsStore.replaceClipsForFile(file.id, loadResult.clips, loadResult.availableMorphTargets);
      }
      projectStore.setFileStats(file.id, loadResult.stats);
    })
    .catch((err) => logger.warn('file-tabs', 'load failed', { err: String(err) }));
}

function setTarget(id: string) {
  projectStore.setTarget(id);
}

function openRemoveFileDialog(id: string) {
  const file = projectStore.files.find((item) => item.id === id);
  removeFileDialog.value = {
    visible: true,
    fileId: id,
    fileName: file?.name ?? '该文件',
  };
}

function closeRemoveFileDialog() {
  removeFileDialog.value = {
    visible: false,
    fileId: '',
    fileName: '',
  };
}

function confirmRemoveFile() {
  const targetFileId = removeFileDialog.value.fileId;
  if (!targetFileId) {
    closeRemoveFileDialog();
    return;
  }

  closeRemoveFileDialog();

  const wasActive = projectStore.activeFileId === targetFileId;
  projectStore.removeFile(targetFileId);
  clipsStore.removeClipsForFile(targetFileId);
  threePreview.unloadFile(targetFileId);

  if (wasActive && projectStore.activeFileId) {
    setActive(projectStore.activeFileId);
  }
}
</script>
