<template>
  <div class="flex h-full min-h-0 flex-col rounded-lg border border-slate-700 bg-slate-900/70 p-3">
    <p class="text-xs font-semibold uppercase tracking-wide text-slate-400">参数面板</p>

    <div v-if="selected" class="mt-3 space-y-4 overflow-auto pr-1">
      <section class="space-y-3">
        <div class="space-y-1">
          <label class="text-xs text-slate-400">Clip Name</label>
          <input
            data-testid="clip-name-input"
            class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
            :value="selected.currentName"
            @input="onNameInput"
          />
          <p v-if="renameError" class="text-[11px] text-rose-300">{{ renameError }}</p>
        </div>

        <div class="space-y-1 rounded-md border border-slate-700 bg-slate-950/40 p-2.5">
          <div class="flex items-center justify-between text-[11px] text-slate-400">
            <span>预览速度（m/s）</span>
            <span>{{ previewSpeedMps.toFixed(2) }}</span>
          </div>
          <input
            data-testid="preview-speed-slider"
            class="h-1 w-full cursor-pointer accent-blue-500"
            type="range"
            min="0"
            max="8"
            step="0.05"
            :value="previewSpeedMps"
            @input="onPreviewSpeedInput"
          />
        </div>

        <div class="space-y-1">
          <label class="text-xs text-slate-400">Authored Speed (m/s)</label>
          <input
            class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
            type="number"
            step="0.1"
            :value="selected.meta.authoredSpeedMps"
            @input="onNumberInput('authoredSpeedMps', $event)"
          />
        </div>

        <div class="grid grid-cols-2 gap-2">
          <div class="space-y-1">
            <label class="text-xs text-slate-400">Min Scale</label>
            <input
              class="w-full rounded-md bg-slate-800 px-2 py-1.5 text-xs"
              :class="scaleRangeInvalid ? 'border border-rose-500' : 'border border-slate-600'"
              type="number"
              step="0.05"
              :value="selected.meta.minScale"
              @input="onNumberInput('minScale', $event)"
            />
          </div>
          <div class="space-y-1">
            <label class="text-xs text-slate-400">Max Scale</label>
            <input
              class="w-full rounded-md bg-slate-800 px-2 py-1.5 text-xs"
              :class="scaleRangeInvalid ? 'border border-rose-500' : 'border border-slate-600'"
              type="number"
              step="0.05"
              :value="selected.meta.maxScale"
              @input="onNumberInput('maxScale', $event)"
            />
          </div>
        </div>

        <div class="space-y-1">
          <label class="text-xs text-slate-400">Default Scale</label>
          <input
            class="w-full rounded-md bg-slate-800 px-2 py-1.5 text-xs"
            :class="defaultScaleInvalid ? 'border border-rose-500' : 'border border-slate-600'"
            type="number"
            step="0.05"
            :value="selected.meta.defaultScale"
            @input="onNumberInput('defaultScale', $event)"
          />
        </div>

        <p v-if="scaleRangeInvalid" class="text-[11px] text-rose-300">minScale 不能大于 maxScale</p>
        <p v-if="defaultScaleInvalid" class="text-[11px] text-rose-300">defaultScale 必须在 0.1 到 5 之间</p>

        <div class="grid grid-cols-2 gap-2">
          <label class="space-y-1">
            <span class="text-xs text-slate-400">Gait</span>
            <select
              class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
              :value="selected.meta.gait"
              @change="onGaitChange"
            >
              <option class="bg-slate-800" value="idle">idle</option>
              <option class="bg-slate-800" value="walk">walk</option>
              <option class="bg-slate-800" value="run">run</option>
              <option class="bg-slate-800" value="jump">jump</option>
              <option class="bg-slate-800" value="fall">fall</option>
              <option class="bg-slate-800" value="other">other</option>
            </select>
          </label>

          <label class="space-y-1">
            <span class="text-xs text-slate-400">Loop</span>
            <select
              class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
              :value="String(selected.meta.loop)"
              @change="onLoopChange"
            >
              <option class="bg-slate-800" value="true">true</option>
              <option class="bg-slate-800" value="false">false</option>
            </select>
          </label>
        </div>

        <button
          class="w-full rounded-md border border-blue-500 px-3 py-1.5 text-xs text-blue-200 hover:bg-blue-500/20"
          type="button"
          @click="resetMeta"
        >
          重置为计算值
        </button>

        <button
          data-testid="delete-clip-btn"
          class="w-full rounded-md border border-rose-500 px-3 py-1.5 text-xs text-rose-200 hover:bg-rose-500/20"
          type="button"
          @click="openDeleteClipDialog"
        >
          删除当前动画
        </button>
      </section>

      <section class="space-y-3 rounded-md border border-slate-700 bg-slate-950/40 p-3">
        <div class="flex items-center gap-2">
          <p class="text-xs font-semibold uppercase tracking-wide text-slate-300">形变验证（Morph Targets）</p>
        </div>

        <p class="text-[11px] leading-5 text-slate-500">仅展示当前 glTF 实际加载到的 morph targets，不再做预设语义映射。</p>

        <div v-if="selectedMorphValidation.channels.length" class="space-y-2">
          <div
            v-for="item in selectedMorphValidation.channels"
            :key="item.channel"
            class="space-y-1"
          >
            <div class="flex items-center justify-between gap-3 text-[11px] text-slate-400">
              <span class="truncate">{{ item.channel }}</span>
              <span>{{ item.weight.toFixed(2) }}</span>
            </div>
            <input
              :data-testid="`morph-slider-${item.channel}`"
              class="w-full accent-blue-500"
              type="range"
              min="0"
              max="1"
              step="0.01"
              :value="item.weight"
              @input="onMorphWeightInput(item.channel, $event)"
            />
          </div>
        </div>

        <div
          v-else
          class="rounded-md border border-dashed border-slate-700 px-3 py-4 text-center text-[11px] text-slate-500"
        >
          当前模型未检测到 morph targets
        </div>

        <button
          class="w-full rounded-md border border-slate-600 px-3 py-1.5 text-xs text-slate-200 hover:bg-slate-800"
          type="button"
          @click="resetMorphValidation"
        >
          重置形变验证
        </button>
      </section>
    </div>

    <div
      v-if="deleteClipDialog.visible"
      class="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/70 px-4"
      data-testid="delete-clip-dialog"
    >
      <div class="w-full max-w-md rounded-lg border border-rose-500/60 bg-slate-900 p-4 shadow-xl">
        <p class="text-sm font-semibold text-rose-200">确认删除动画</p>
        <p class="mt-2 text-xs text-slate-300">确认删除动画「{{ deleteClipDialog.clipName }}」吗？该操作不可撤销。</p>
        <div class="mt-4 flex items-center justify-end gap-2">
          <button
            type="button"
            class="rounded border border-slate-600 px-3 py-1.5 text-xs text-slate-300 hover:bg-slate-800"
            @click="closeDeleteClipDialog"
          >
            取消
          </button>
          <button
            data-testid="confirm-delete-clip-btn"
            type="button"
            class="rounded border border-rose-500 px-3 py-1.5 text-xs text-rose-200 hover:bg-rose-500/20"
            @click="confirmDeleteClip"
          >
            确认删除
          </button>
        </div>
      </div>
    </div>

    <div v-if="!selected" class="mt-8 rounded-md border border-dashed border-slate-700 p-4 text-center text-xs text-slate-500">
      请选择动画片段查看参数
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue';

import type { AnimMeta } from '../types/anim-meta';

import { logger } from '../services/logger';
import { computePreviewTimeScale } from '../services/param-compute';
import { threePreview } from '../services/three-preview';
import { createDefaultMorphValidation } from '../shared/morph-validation';
import { useClipsStore } from '../stores/clips';

const clipsStore = useClipsStore();

const selected = computed(() => clipsStore.selectedClip);
const selectedMorphValidation = computed(() => selected.value?.morphValidation ?? createDefaultMorphValidation());
const renameError = ref('');
const previewSpeedMps = ref(0);
const deleteClipDialog = ref({
  visible: false,
  clipId: '',
  clipName: '',
});

const scaleRangeInvalid = computed(() => {
  if (!selected.value) {
    return false;
  }
  return selected.value.meta.minScale > selected.value.meta.maxScale;
});

const defaultScaleInvalid = computed(() => {
  if (!selected.value) {
    return false;
  }
  return selected.value.meta.defaultScale < 0.1 || selected.value.meta.defaultScale > 5;
});

watch(
  () => selected.value?.id,
  () => {
    renameError.value = '';
    previewSpeedMps.value = selected.value?.meta.authoredSpeedMps ?? 0;
  },
  { immediate: true },
);

watch(
  [selected, previewSpeedMps],
  () => {
    if (!selected.value) {
      return;
    }
    const timeScale = computePreviewTimeScale(selected.value.meta, previewSpeedMps.value);
    threePreview.setTimeScale(timeScale);
    logger.info('param-panel', 'preview speed applied', {
      clipId: selected.value.id,
      previewSpeedMps: previewSpeedMps.value,
      timeScale,
    });
  },
  { deep: true },
);

function onNameInput(event: Event) {
  if (!clipsStore.selectedClip) {
    return;
  }
  const { value } = event.target as HTMLInputElement;
  const result = clipsStore.renameClip(clipsStore.selectedClip.id, value);
  if (result.ok) {
    renameError.value = '';
    return;
  }

  if (result.conflict) {
    renameError.value = `命名冲突：当前文件已有同名动画（${result.conflict}）`;
    return;
  }

  if (result.reason === 'empty') {
    renameError.value = '名称不能为空';
    return;
  }

  if (result.reason === 'too_long') {
    renameError.value = '名称长度不能超过 64';
    return;
  }

  if (result.reason === 'invalid_chars') {
    renameError.value = '仅允许字母、数字、下划线和中划线';
    return;
  }

  renameError.value = '改名失败，请重试';
}

function onNumberInput(
  field: keyof Pick<AnimMeta, 'authoredSpeedMps' | 'minScale' | 'maxScale' | 'defaultScale'>,
  event: Event,
) {
  if (!clipsStore.selectedClip) {
    return;
  }
  const value = Number((event.target as HTMLInputElement).value);
  if (Number.isNaN(value)) {
    return;
  }
  clipsStore.updateMeta(clipsStore.selectedClip.id, { [field]: value });
}

function onGaitChange(event: Event) {
  if (!clipsStore.selectedClip) {
    return;
  }
  clipsStore.updateMeta(clipsStore.selectedClip.id, {
    gait: (event.target as HTMLSelectElement).value as AnimMeta['gait'],
  });
}

function onLoopChange(event: Event) {
  if (!clipsStore.selectedClip) {
    return;
  }
  clipsStore.updateMeta(clipsStore.selectedClip.id, {
    loop: (event.target as HTMLSelectElement).value === 'true',
  });
}

function onMorphWeightInput(channel: string, event: Event) {
  if (!clipsStore.selectedClip) {
    return;
  }
  const value = Number((event.target as HTMLInputElement).value);
  if (Number.isNaN(value)) {
    return;
  }
  clipsStore.updateMorphWeight(clipsStore.selectedClip.id, channel, value);
}

function onPreviewSpeedInput(event: Event) {
  const value = Number((event.target as HTMLInputElement).value);
  if (Number.isNaN(value)) {
    return;
  }
  previewSpeedMps.value = value;
}

function resetMeta() {
  if (!clipsStore.selectedClip) {
    return;
  }
  clipsStore.resetMeta(clipsStore.selectedClip.id);
  previewSpeedMps.value = clipsStore.selectedClip.meta.authoredSpeedMps;
}

function resetMorphValidation() {
  if (!clipsStore.selectedClip) {
    return;
  }
  clipsStore.resetMorphValidation(clipsStore.selectedClip.id);
}

function openDeleteClipDialog() {
  if (!clipsStore.selectedClip) {
    return;
  }
  deleteClipDialog.value = {
    visible: true,
    clipId: clipsStore.selectedClip.id,
    clipName: clipsStore.selectedClip.currentName,
  };
}

function closeDeleteClipDialog() {
  deleteClipDialog.value = {
    visible: false,
    clipId: '',
    clipName: '',
  };
}

function confirmDeleteClip() {
  const {clipId} = deleteClipDialog.value;
  const {clipName} = deleteClipDialog.value;
  if (!clipId) {
    closeDeleteClipDialog();
    return;
  }

  closeDeleteClipDialog();

  const ok = clipsStore.deleteClip(clipId);
  if (!ok) {
    logger.warn('param-panel', 'delete clip failed', {
      clipId,
      clipName,
    });
    return;
  }

  renameError.value = '';
}
</script>
