<template>
  <div
    class="rounded-lg border-2 border-dashed p-4 text-center transition"
    :class="isHovering ? 'animate-pulse border-blue-400 bg-blue-500/10' : 'border-slate-600 bg-slate-800/50'"
    @dragenter.prevent="isHovering = true"
    @dragleave.prevent="isHovering = false"
    @dragover.prevent="isHovering = true"
    @drop.prevent="onDrop"
  >
    <p class="text-xs text-slate-300">拖拽 GLB/GLTF 到这里</p>
    <p class="mt-1 text-[11px] text-slate-500">支持 Draco 压缩；本地 public/draco 已就绪</p>
    <input
      ref="inputRef"
      class="hidden"
      type="file"
      accept=".gltf,.glb"
      multiple
      @change="onPick"
    />
    <button
      class="mt-3 rounded-md border border-slate-500 px-3 py-1.5 text-xs hover:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-60"
      :disabled="isImporting"
      type="button"
      @click="inputRef?.click()"
    >
      {{ isImporting ? '导入中…' : '选择文件导入' }}
    </button>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue';

import { importCharacterFiles } from '../services/file-import';

const isHovering = ref(false);
const isImporting = ref(false);
const inputRef = ref<HTMLInputElement | null>(null);

async function importFiles(fileList: FileList | File[]) {
  if (isImporting.value) {
    return;
  }

  isImporting.value = true;
  try {
    await importCharacterFiles(fileList);
  } finally {
    isImporting.value = false;
  }
}

function onDrop(event: DragEvent) {
  isHovering.value = false;
  const files = event.dataTransfer?.files;
  if (!files?.length) {
    return;
  }
  void importFiles(files);
}

function onPick(event: Event) {
  const target = event.target as HTMLInputElement;
  if (!target.files) {
    return;
  }
  void importFiles(target.files);
  target.value = '';
}
</script>
