import { defineStore } from 'pinia';

import { buildMergedName } from '../services/animation-merge';
import { renameClip, type RenameResult } from '../services/animation-rename';
import { logger } from '../services/logger';
import { computeMeta } from '../services/param-compute';
import { threePreview, type MergeClipFailCode } from '../services/three-preview';
import { cloneMorphValidation, normalizeMorphValidation } from '../shared/morph-validation';
import { useProjectStore } from './project';
import type { AnimMeta, MorphValidationState } from '../types/anim-meta';
import type { ClipEntry } from '../types/project';

function normalizeClip(clip: ClipEntry): ClipEntry {
  return {
    ...clip,
    morphValidation: normalizeMorphValidation((clip as ClipEntry & { morphValidation?: MorphValidationState }).morphValidation),
  };
}

function cloneMeta(meta: AnimMeta): AnimMeta {
  return {
    ...meta,
  };
}

export interface ClipMergeIssue {
  sourceClipId: string;
  sourceFileId: string;
  sourceClipName: string;
  mergedName: string;
  code: MergeClipFailCode;
  missingNodeMappings: string[];
  droppedTrackCount: number;
  droppedBoneScaleTrackCount: number;
  parseFailedTrackName?: string;
}

export interface MergeClipsResult {
  mergedCount: number;
  mergedClipNames: string[];
  issues: ClipMergeIssue[];
  force: boolean;
}

export const useClipsStore = defineStore('character-clips', {
  state: (): { clips: ClipEntry[]; selectedClipId: string | null } => ({
    clips: [],
    selectedClipId: null,
  }),
  getters: {
    selectedClip(state): ClipEntry | null {
      const clip = state.clips.find((item) => item.id === state.selectedClipId);
      if (!clip) {
        return null;
      }
      return normalizeClip(clip);
    },
  },
  actions: {
    selectClip(id: string) {
      this.selectedClipId = id;
    },
    renameClip(id: string, name: string): RenameResult {
      const targetBeforeRename = this.clips.find((clip) => clip.id === id);
      const result = renameClip(this.clips, id, name);
      if (!result.ok) {
        logger.warn('clips-store', 'renameClip rejected', { id, name, reason: result.reason, conflict: result.conflict });
        return result;
      }

      this.clips = result.nextClips ?? this.clips;

      if (targetBeforeRename) {
        const renamedClip = this.clips.find((clip) => clip.id === id);
        const renameApplied = threePreview.renameClip(
          targetBeforeRename.fileId,
          targetBeforeRename.currentName,
          renamedClip?.currentName ?? name,
        );
        if (!renameApplied) {
          logger.warn('clips-store', 'renameClip preview rename skipped', {
            fileId: targetBeforeRename.fileId,
            from: targetBeforeRename.currentName,
            to: renamedClip?.currentName ?? name,
          });
        }
      }

      logger.info('clips-store', 'renameClip called', { id, name });
      return result;
    },
    deleteClip(id: string): boolean {
      const projectStore = useProjectStore();
      const target = this.clips.find((clip) => clip.id === id);
      if (!target) {
        logger.warn('clips-store', 'deleteClip skipped: clip not found', { id });
        return false;
      }

      const removed = threePreview.removeClip(target.fileId, target.currentName);
      if (!removed) {
        logger.warn('clips-store', 'deleteClip preview remove skipped', {
          fileId: target.fileId,
          clipName: target.currentName,
        });
      }

      const remaining = this.clips.filter((clip) => clip.id !== id);
      this.clips = remaining;

      const sameFileNext = remaining.find((clip) => clip.fileId === target.fileId)?.id ?? null;
      const globalNext = remaining[0]?.id ?? null;
      if (this.selectedClipId === id) {
        this.selectedClipId = sameFileNext ?? globalNext;
      }

      const animationCount = remaining.filter((clip) => clip.fileId === target.fileId).length;
      projectStore.setAnimationCount(target.fileId, animationCount);

      logger.info('clips-store', 'deleteClip success', {
        id,
        fileId: target.fileId,
        clipName: target.currentName,
        animationCount,
        selectedClipId: this.selectedClipId,
      });
      return true;
    },
    mergeClips(targetFileId: string, clipIds: string[], options?: { force?: boolean }): MergeClipsResult {
      const projectStore = useProjectStore();
      const selectedClips = this.clips.filter((clip) => clipIds.includes(clip.id));
      const force = Boolean(options?.force);

      if (!selectedClips.length) {
        logger.warn('clips-store', 'mergeClips skipped: no selected clips', { targetFileId, force });
        return { mergedCount: 0, mergedClipNames: [], issues: [], force };
      }

      const targetExistingNames = new Set(
        this.clips.filter((clip) => clip.fileId === targetFileId).map((clip) => clip.currentName),
      );

      const mergedClips: ClipEntry[] = [];
      const issues: ClipMergeIssue[] = [];
      selectedClips
        .filter((clip) => clip.fileId !== targetFileId)
        .forEach((clip, index) => {
          const safeClip = normalizeClip(clip);
          const mergedName = buildMergedName(safeClip.currentName, targetExistingNames);

          const injected = threePreview.mergeClipToFile(safeClip.fileId, safeClip.currentName, targetFileId, mergedName, { force });
          if (!injected.ok) {
            issues.push({
              sourceClipId: safeClip.id,
              sourceFileId: safeClip.fileId,
              sourceClipName: safeClip.currentName,
              mergedName,
              code: injected.code ?? 'no_compatible_tracks',
              missingNodeMappings: injected.missingNodeMappings,
              droppedTrackCount: injected.droppedTrackCount,
              droppedBoneScaleTrackCount: injected.droppedBoneScaleTrackCount,
              parseFailedTrackName: injected.parseFailedTrackName,
            });
            logger.warn('clips-store', 'mergeClips skipped: preview clip inject failed', {
              sourceClipId: safeClip.id,
              sourceFileId: safeClip.fileId,
              sourceClipName: safeClip.currentName,
              targetFileId,
              mergedName,
              code: injected.code,
              missingNodeMappings: injected.missingNodeMappings,
              force,
            });
            return;
          }

          targetExistingNames.add(mergedName);
          mergedClips.push({
            ...safeClip,
            id: `${targetFileId}::${mergedName}::merged_${Date.now()}_${index}`,
            fileId: targetFileId,
            originalName: mergedName,
            currentName: mergedName,
            meta: {
              ...cloneMeta(safeClip.meta),
              name: mergedName,
            },
            computedMeta: {
              ...cloneMeta(safeClip.computedMeta),
              name: mergedName,
            },
            morphValidation: cloneMorphValidation(safeClip.morphValidation),
          });
        });

      if (!mergedClips.length) {
        logger.warn('clips-store', 'mergeClips skipped: no playable clips merged', { targetFileId, clipIds, force, issues });
        return { mergedCount: 0, mergedClipNames: [], issues, force };
      }

      this.clips = [...this.clips, ...mergedClips];
      const targetCount = this.clips.filter((clip) => clip.fileId === targetFileId).length;
      projectStore.setAnimationCount(targetFileId, targetCount);

      const mergedClipNames = mergedClips.map((clip) => clip.currentName);
      logger.info('clips-store', 'mergeClips success', {
        targetFileId,
        force,
        mergedCount: mergedClips.length,
        mergedClipNames,
        issueCount: issues.length,
      });

      return {
        mergedCount: mergedClips.length,
        mergedClipNames,
        issues,
        force,
      };
    },
    updateMeta(id: string, patch: Partial<AnimMeta>) {
      this.clips = this.clips.map((clip) => {
        if (clip.id !== id) {
          return clip;
        }
        return {
          ...clip,
          meta: {
            ...clip.meta,
            ...patch,
          },
        };
      });
      logger.info('clips-store', 'updateMeta called', { id, patch });
    },
    updateMorphWeight(id: string, channel: string, weight: number) {
      const nextWeight = Math.min(1, Math.max(0, weight));
      this.clips = this.clips.map((clip) => {
        if (clip.id !== id) {
          return clip;
        }

        const morph = normalizeMorphValidation((clip as ClipEntry & { morphValidation?: MorphValidationState }).morphValidation);
        return {
          ...clip,
          morphValidation: {
            channels: morph.channels.map((item) =>
              item.channel === channel ? { ...item, weight: nextWeight } : item,
            ),
          },
        };
      });
      logger.info('clips-store', 'updateMorphWeight called', { id, channel, weight: nextWeight });
    },
    resetMorphValidation(id: string) {
      this.clips = this.clips.map((clip) => {
        if (clip.id !== id) {
          return clip;
        }

        const morph = normalizeMorphValidation((clip as ClipEntry & { morphValidation?: MorphValidationState }).morphValidation);
        return {
          ...clip,
          morphValidation: {
            channels: morph.channels.map((item) => ({ ...item, weight: 0 })),
          },
        };
      });
      logger.info('clips-store', 'resetMorphValidation called', { id });
    },
    resetMeta(id: string) {
      this.clips = this.clips.map((clip) => {
        if (clip.id !== id) {
          return clip;
        }
        return {
          ...clip,
          meta: cloneMeta(clip.computedMeta),
        };
      });
      logger.info('clips-store', 'resetMeta called', { id });
    },
    removeClipsForFile(fileId: string) {
      const remaining = this.clips.filter((clip) => clip.fileId !== fileId);
      this.clips = remaining;

      if (this.selectedClipId && !remaining.some((clip) => clip.id === this.selectedClipId)) {
        this.selectedClipId = remaining[0]?.id ?? null;
      }

      logger.info('clips-store', 'removeClipsForFile called', {
        fileId,
        remainingCount: remaining.length,
        selectedClipId: this.selectedClipId,
      });
    },
    /**
     * 阶段 2：用真实 GLTF 解析出的动画描述符替换某 fileId 下所有 clips。
     * - duration / frameCount 来自 three（frameCount 用 30fps 估算，仅用于 UI 展示）
     * - meta / computedMeta 暂以 gait="other"、loop=true 占位，后续阶段由 param-compute 真值替换
     * - morphValidation 直接使用当前 glTF 实际存在的 morph target 名，保证 ParamPanel 与预览一致
     */
    replaceClipsForFile(
      fileId: string,
      descriptors: { name: string; duration: number }[],
      availableMorphTargets?: string[],
    ) {
      const projectStore = useProjectStore();
      const remaining = this.clips.filter((clip) => clip.fileId !== fileId);
      const fresh: ClipEntry[] = descriptors.map((desc, index) => {
        const baseMeta: AnimMeta = computeMeta({
          name: desc.name,
          duration: desc.duration,
        });
        return {
          id: `${fileId}::${desc.name}::${index}`,
          fileId,
          originalName: desc.name,
          currentName: desc.name,
          duration: desc.duration,
          frameCount: Math.max(1, Math.round(desc.duration * 30)),
          meta: { ...baseMeta },
          computedMeta: { ...baseMeta },
          morphValidation: cloneMorphValidation(undefined, availableMorphTargets),
        };
      });

      this.clips = [...remaining, ...fresh];
      projectStore.setAnimationCount(fileId, fresh.length);

      const stillSelected = fresh.some((clip) => clip.id === this.selectedClipId);
      if (!stillSelected) {
        this.selectedClipId = fresh[0]?.id ?? null;
      }

      logger.info('clips-store', 'replaceClipsForFile success', {
        fileId,
        clipCount: fresh.length,
      });
    },
  },
});
