<template>
  <div class="flex h-full min-h-0 flex-col">
    <div class="flex items-center justify-between gap-2">
      <p class="text-xs font-semibold uppercase tracking-wide text-slate-400">动画片段</p>
      <span class="text-[11px] text-slate-500">{{ sourceName }} → {{ targetName }}</span>
    </div>

    <div class="mt-2 rounded-md border border-slate-700 bg-slate-900/80 p-2">
      <div class="flex items-center justify-between gap-2 text-[11px]">
        <p class="text-slate-300">已选中 {{ mergeCandidateIds.length }} 个待合并动画</p>
        <button
          data-testid="merge-to-target-btn"
          class="rounded border px-2 py-1 transition"
          :class="canMerge ? 'border-blue-500 text-blue-200 hover:bg-blue-500/20' : 'border-slate-700 text-slate-500'"
          :disabled="!canMerge"
          type="button"
          @click="mergeToTarget"
        >
          合并到目标模型
        </button>
      </div>
      <p v-if="isSourceTargetSame" class="mt-1 text-[11px] text-amber-300">当前来源文件就是目标模型，无法执行合并。</p>
    </div>

    <div class="mt-2 min-h-0 flex-1 overflow-auto rounded-md border border-slate-700 bg-slate-900/70">
      <table class="w-full border-collapse text-xs">
        <thead class="sticky top-0 bg-slate-900 text-slate-400">
          <tr>
            <th class="w-10 px-2 py-2 text-center font-medium">合并</th>
            <th class="px-2 py-2 text-left font-medium">名称</th>
            <th class="px-2 py-2 text-right font-medium">时长</th>
            <th class="px-2 py-2 text-right font-medium">帧数</th>
            <th class="px-2 py-2 text-center font-medium">Loop</th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="clip in visibleClips"
            :key="clip.id"
            class="cursor-pointer border-t border-slate-800 transition hover:bg-slate-800/80"
            :class="clip.id === clipsStore.selectedClipId ? 'bg-blue-500/20 text-blue-100' : 'text-slate-200'"
            @click="onClipRowClick(clip.id)"
          >
            <td class="px-2 py-2 text-center">
              <input
                class="h-3.5 w-3.5 cursor-pointer accent-blue-500"
                type="checkbox"
                :checked="mergeCandidateIds.includes(clip.id)"
                :disabled="isSourceTargetSame"
                @click.stop
                @change="toggleMergeCandidate(clip.id, $event)"
              />
            </td>
            <td class="max-w-[120px] truncate px-2 py-2">{{ clip.currentName }}</td>
            <td class="px-2 py-2 text-right">{{ clip.duration.toFixed(2) }}s</td>
            <td class="px-2 py-2 text-right">{{ clip.frameCount }}</td>
            <td class="px-2 py-2 text-center">
              <input
                :data-testid="`loop-checkbox-${clip.id}`"
                class="h-3.5 w-3.5 cursor-pointer accent-blue-500"
                type="checkbox"
                :checked="clip.meta.loop"
                @click.stop
                @change="toggleClipLoop(clip.id, $event)"
              />
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <div
      v-if="mergeErrorDialog.visible"
      class="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/70 px-4"
      data-testid="merge-error-dialog"
    >
      <div class="w-full max-w-xl rounded-lg border border-rose-500/60 bg-slate-900 p-4 shadow-xl">
        <p class="text-sm font-semibold text-rose-200">合并失败（严格模式）</p>
        <p class="mt-2 text-xs text-slate-300">以下动画未能按严格映射规则合并：</p>
        <ul class="mt-2 max-h-52 space-y-2 overflow-auto text-[11px] text-slate-300">
          <li v-for="item in mergeErrorDialog.items" :key="item.sourceClipId" class="rounded border border-slate-700 bg-slate-950/60 p-2">
            <p class="font-medium text-slate-100">{{ item.sourceClipName }}</p>
            <p class="mt-1 text-slate-300">原因：{{ item.message }}</p>
          </li>
        </ul>

        <div class="mt-4 flex items-center justify-end gap-2">
          <button
            type="button"
            class="rounded border border-slate-600 px-3 py-1.5 text-xs text-slate-300 hover:bg-slate-800"
            @click="closeMergeErrorDialog"
          >
            关闭
          </button>
          <button
            data-testid="force-merge-btn"
            type="button"
            class="rounded border border-amber-500 px-3 py-1.5 text-xs text-amber-200 hover:bg-amber-500/20"
            @click="forceMergeFailedClips"
          >
            强制合并（保留可映射轨道）
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue';

import { logger } from '../services/logger';
import { threePreview } from '../services/three-preview';
import { useClipsStore, type ClipMergeIssue, type MergeClipsResult } from '../stores/clips';
import { useProjectStore } from '../stores/project';

const clipsStore = useClipsStore();
const projectStore = useProjectStore();
const mergeCandidateIds = ref<string[]>([]);
const mergeErrorDialog = ref<{
  visible: boolean;
  targetFileId: string;
  failedClipIds: string[];
  items: { sourceClipId: string; sourceClipName: string; message: string }[];
}>({
  visible: false,
  targetFileId: '',
  failedClipIds: [],
  items: [],
});

const visibleClips = computed(() => {
  const { activeFileId } = projectStore;
  return clipsStore.clips.filter((clip) => clip.fileId === activeFileId);
});

const sourceName = computed(() => projectStore.activeFile?.name ?? '未选择来源');
const targetName = computed(() => projectStore.targetFile?.name ?? '未选择目标');
const isSourceTargetSame = computed(
  () =>
    !projectStore.activeFileId || !projectStore.targetFileId || projectStore.activeFileId === projectStore.targetFileId,
);
const canMerge = computed(() => !isSourceTargetSame.value && mergeCandidateIds.value.length > 0);

watch(
  visibleClips,
  (clips) => {
    if (!clips.length) {
      clipsStore.selectedClipId = null;
      mergeCandidateIds.value = [];
      return;
    }

    const existed = clips.some((clip) => clip.id === clipsStore.selectedClipId);
    if (!existed) {
      clipsStore.selectClip(clips[0].id);
    }

    const visibleIds = new Set(clips.map((clip) => clip.id));
    mergeCandidateIds.value = mergeCandidateIds.value.filter((id) => visibleIds.has(id));
  },
  { immediate: true },
);

function onClipRowClick(id: string) {
  const clip = clipsStore.clips.find((item) => item.id === id);
  logger.info('animation-list', 'clip row clicked', {
    clickedId: id,
    clickedName: clip?.currentName,
    originalName: clip?.originalName,
    beforeSelectedClipId: clipsStore.selectedClipId,
    activeFileId: projectStore.activeFileId,
  });
  clipsStore.selectClip(id);
}

function toggleMergeCandidate(id: string, event: Event) {
  const { checked } = event.target as HTMLInputElement;
  if (checked) {
    if (!mergeCandidateIds.value.includes(id)) {
      mergeCandidateIds.value = [...mergeCandidateIds.value, id];
    }
    return;
  }

  mergeCandidateIds.value = mergeCandidateIds.value.filter((item) => item !== id);
}

function toggleClipLoop(id: string, event: Event) {
  const { checked } = event.target as HTMLInputElement;
  clipsStore.updateMeta(id, { loop: checked });
}

function mapIssueToMessage(issue: ClipMergeIssue): string {
  if (issue.code === 'strict_node_mapping_failed') {
    const missing = issue.missingNodeMappings.slice(0, 4).join('、');
    const suffix = issue.missingNodeMappings.length > 4 ? ' 等' : '';
    return `存在无法映射的骨骼节点：${missing}${suffix}`;
  }
  if (issue.code === 'track_parse_failed') {
    return issue.parseFailedTrackName
      ? `轨道解析失败：${issue.parseFailedTrackName}`
      : '轨道解析失败';
  }
  if (issue.code === 'no_compatible_tracks') {
    return '可用轨道为空（可能全部被过滤或未命中节点）';
  }
  if (issue.code === 'source_clip_not_found') {
    return '来源动画不存在';
  }
  if (issue.code === 'source_or_target_not_loaded') {
    return '来源或目标模型未加载完成';
  }
  if (issue.code === 'merged_name_conflict') {
    return '目标模型已存在同名动画';
  }
  if (issue.code === 'empty_merged_name') {
    return '合并动画名为空';
  }
  return '未知错误';
}

function closeMergeErrorDialog() {
  mergeErrorDialog.value = {
    visible: false,
    targetFileId: '',
    failedClipIds: [],
    items: [],
  };
}

function openMergeErrorDialog(targetFileId: string, result: MergeClipsResult) {
  if (!result.issues.length) {
    closeMergeErrorDialog();
    return;
  }
  mergeErrorDialog.value = {
    visible: true,
    targetFileId,
    failedClipIds: result.issues.map((item) => item.sourceClipId),
    items: result.issues.map((item) => ({
      sourceClipId: item.sourceClipId,
      sourceClipName: item.sourceClipName,
      message: mapIssueToMessage(item),
    })),
  };
}

function applyMergeResult(targetFileId: string, result: MergeClipsResult) {
  if (result.mergedCount > 0) {
    projectStore.setActive(targetFileId);
  }

  if (result.issues.length > 0 && !result.force) {
    openMergeErrorDialog(targetFileId, result);
  } else {
    closeMergeErrorDialog();
  }
}

async function forceMergeFailedClips() {
  if (!mergeErrorDialog.value.failedClipIds.length || !mergeErrorDialog.value.targetFileId) {
    closeMergeErrorDialog();
    return;
  }

  const {targetFileId} = mergeErrorDialog.value;
  const result = clipsStore.mergeClips(targetFileId, mergeErrorDialog.value.failedClipIds, { force: true });
  if (result.issues.length > 0) {
    mergeErrorDialog.value = {
      ...mergeErrorDialog.value,
      visible: true,
      items: result.issues.map((item) => ({
        sourceClipId: item.sourceClipId,
        sourceClipName: item.sourceClipName,
        message: mapIssueToMessage(item),
      })),
      failedClipIds: result.issues.map((item) => item.sourceClipId),
    };
    return;
  }

  closeMergeErrorDialog();
  if (result.mergedCount > 0) {
    projectStore.setActive(targetFileId);
  }
}

async function mergeToTarget() {
  if (!projectStore.targetFileId || !canMerge.value) {
    return;
  }

  const { activeFile: sourceFile, targetFile } = projectStore;
  if (!sourceFile?.arrayBuffer || !targetFile?.arrayBuffer) {
    logger.warn('animation-list', 'merge skipped: source or target file buffer missing', {
      sourceFileId: sourceFile?.id,
      targetFileId: targetFile?.id,
    });
    return;
  }

  await Promise.all([
    threePreview.load(sourceFile.arrayBuffer, sourceFile.id),
    threePreview.load(targetFile.arrayBuffer, targetFile.id),
  ]);

  const mergeResult = clipsStore.mergeClips(projectStore.targetFileId, mergeCandidateIds.value, { force: false });
  mergeCandidateIds.value = [];
  applyMergeResult(projectStore.targetFileId, mergeResult);
}
</script>
