import type { MorphValidationState } from '../types/anim-meta';

function normalizeChannelList(channels?: readonly string[]): string[] {
  return Array.from(new Set((channels ?? []).filter(Boolean)));
}

export function createDefaultMorphValidation(channels?: readonly string[]): MorphValidationState {
  const normalizedChannels = normalizeChannelList(channels);
  return {
    channels: normalizedChannels.map((channel) => ({ channel, weight: 0 })),
  };
}

export function normalizeMorphValidation(
  validation?: MorphValidationState,
  channels?: readonly string[],
): MorphValidationState {
  const normalizedChannels = normalizeChannelList(channels ?? validation?.channels.map((item) => item.channel));
  if (!validation) {
    return createDefaultMorphValidation(normalizedChannels);
  }

  const existed = new Map(validation.channels.map((item) => [item.channel, item.weight]));
  return {
    channels: normalizedChannels.map((channel) => ({
      channel,
      weight: Math.min(1, Math.max(0, existed.get(channel) ?? 0)),
    })),
  };
}

export function cloneMorphValidation(validation?: MorphValidationState, channels?: readonly string[]): MorphValidationState {
  const normalized = normalizeMorphValidation(validation, channels);
  return {
    channels: normalized.channels.map((item) => ({ ...item })),
  };
}
