import { Format, WebIO, type Document as GltfDocument, type JSONDocument } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { draco } from '@gltf-transform/functions';
import decoderScriptUrl from 'draco3dgltf/draco_decoder_gltf_nodejs.js?url';
import decoderWasmUrl from 'draco3dgltf/draco_decoder_gltf.wasm?url';
import encoderScriptUrl from 'draco3dgltf/draco_encoder_gltf_nodejs.js?url';
import encoderWasmUrl from 'draco3dgltf/draco_encoder.wasm?url';

import { buildDracoTransformOptions, type DracoCustomOptions, type DracoPreset, type ExportFormat } from './export-config';

const GLB_MAGIC = 0x46546c67; // 'glTF'

type DracoGlobalName = 'DracoEncoderModule' | 'DracoDecoderModule';

type DracoModuleFactory = (config?: {
  locateFile?: (fileName: string, scriptDirectory: string) => string;
}) => Promise<unknown>;

declare global {
  interface Window {
    DracoEncoderModule?: DracoModuleFactory;
    DracoDecoderModule?: DracoModuleFactory;
  }
}

export interface SerializedArtifact {
  fileName: string;
  bytes: Uint8Array;
  mimeType: string;
}

export interface SerializeModelOptions {
  fileName: string;
  arrayBuffer: ArrayBuffer;
  format: ExportFormat;
  dracoPreset: DracoPreset;
  dracoCustomOptions?: Partial<DracoCustomOptions>;
}

const runtimeLoaders = new Map<string, Promise<void>>();
let webIOPromise: Promise<WebIO> | null = null;
let encoderModulePromise: Promise<unknown> | null = null;
let decoderModulePromise: Promise<unknown> | null = null;

function stripExtension(fileName: string): string {
  return fileName.replace(/\.[^./\\]+$/, '');
}

function isBinaryGlb(buffer: ArrayBuffer): boolean {
  if (buffer.byteLength < 12) {
    return false;
  }
  return new DataView(buffer).getUint32(0, true) === GLB_MAGIC;
}

function toUint8Array(buffer: ArrayBuffer): Uint8Array {
  return new Uint8Array(buffer.slice(0));
}

function createJsonDocumentFromArrayBuffer(buffer: ArrayBuffer): JSONDocument {
  const jsonText = new TextDecoder().decode(new Uint8Array(buffer));
  return {
    json: JSON.parse(jsonText),
    resources: {},
  };
}

function guessMimeType(fileName: string): string {
  const lower = fileName.toLowerCase();
  if (lower.endsWith('.gltf')) {
    return 'model/gltf+json';
  }
  if (lower.endsWith('.glb')) {
    return 'model/gltf-binary';
  }
  if (lower.endsWith('.bin')) {
    return 'application/octet-stream';
  }
  if (lower.endsWith('.png')) {
    return 'image/png';
  }
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) {
    return 'image/jpeg';
  }
  if (lower.endsWith('.webp')) {
    return 'image/webp';
  }
  if (lower.endsWith('.ktx2')) {
    return 'image/ktx2';
  }
  return 'application/octet-stream';
}

function ensureBrowserDocument(): globalThis.Document {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    throw new Error('Draco 浏览器运行时仅可在 DOM 环境中使用');
  }
  return document;
}

async function loadRuntimeScript(src: string, globalName: DracoGlobalName): Promise<DracoModuleFactory> {
  if (window[globalName]) {
    return window[globalName] as DracoModuleFactory;
  }

  const existingPromise = runtimeLoaders.get(src);
  if (existingPromise) {
    await existingPromise;
    const runtimeFactory = window[globalName];
    if (!runtimeFactory) {
      throw new Error(`Draco 运行时 ${globalName} 加载后未暴露全局工厂`);
    }
    return runtimeFactory;
  }

  const domDocument = ensureBrowserDocument();
  const loadPromise = new Promise<void>((resolve, reject) => {
    const script = domDocument.createElement('script');
    script.async = true;
    script.src = src;
    script.onload = () => resolve();
    script.onerror = () => {
      runtimeLoaders.delete(src);
      reject(new Error(`Draco 运行时脚本加载失败: ${src}`));
    };
    domDocument.head.appendChild(script);
  });

  runtimeLoaders.set(src, loadPromise);
  await loadPromise;

  const runtimeFactory = window[globalName];
  if (!runtimeFactory) {
    throw new Error(`Draco 运行时 ${globalName} 加载后未暴露全局工厂`);
  }
  return runtimeFactory;
}

async function createDracoModule(
  globalName: DracoGlobalName,
  scriptUrl: string,
  wasmUrl: string,
): Promise<unknown> {
  const runtimeFactory = await loadRuntimeScript(scriptUrl, globalName);
  return runtimeFactory({
    locateFile: () => wasmUrl,
  });
}

async function getDracoDependencies(): Promise<Record<'draco3d.encoder' | 'draco3d.decoder', unknown>> {
  encoderModulePromise ??= createDracoModule('DracoEncoderModule', encoderScriptUrl, encoderWasmUrl);
  decoderModulePromise ??= createDracoModule('DracoDecoderModule', decoderScriptUrl, decoderWasmUrl);

  const [encoderModule, decoderModule] = await Promise.all([encoderModulePromise, decoderModulePromise]);
  return {
    'draco3d.encoder': encoderModule,
    'draco3d.decoder': decoderModule,
  };
}

async function getWebIO(): Promise<WebIO> {
  if (!webIOPromise) {
    webIOPromise = (async () => {
      const dependencies = await getDracoDependencies();
      return new WebIO().registerExtensions(ALL_EXTENSIONS).registerDependencies(dependencies);
    })();
  }
  return webIOPromise;
}

async function readDocumentFromBuffer(arrayBuffer: ArrayBuffer): Promise<GltfDocument> {
  const io = await getWebIO();
  if (isBinaryGlb(arrayBuffer)) {
    return io.readBinary(toUint8Array(arrayBuffer));
  }
  return io.readJSON(createJsonDocumentFromArrayBuffer(arrayBuffer));
}

export async function serializeModelWithDraco(options: SerializeModelOptions): Promise<SerializedArtifact[]> {
  const { fileName, arrayBuffer, format, dracoPreset, dracoCustomOptions } = options;
  const io = await getWebIO();
  const baseName = stripExtension(fileName);
  const document = await readDocumentFromBuffer(arrayBuffer);

  const dracoOptions = buildDracoTransformOptions(dracoPreset, dracoCustomOptions);
  if (dracoOptions) {
    await document.transform(draco(dracoOptions));
  }

  if (format === 'glb') {
    const glb = await io.writeBinary(document);
    return [
      {
        fileName: `${baseName}.glb`,
        bytes: glb,
        mimeType: 'model/gltf-binary',
      },
    ];
  }

  const jsonDoc = await io.writeJSON(document, { format: Format.GLTF, basename: baseName });
  const gltfText = JSON.stringify(jsonDoc.json, null, 2);
  const artifacts: SerializedArtifact[] = [
    {
      fileName: `${baseName}.gltf`,
      bytes: new TextEncoder().encode(gltfText),
      mimeType: 'model/gltf+json',
    },
  ];

  for (const [resourceName, resourceBytes] of Object.entries(jsonDoc.resources)) {
    artifacts.push({
      fileName: resourceName,
      bytes: resourceBytes,
      mimeType: guessMimeType(resourceName),
    });
  }

  return artifacts;
}
