import { logger } from './logger';

export interface GltfImportResult {
  /** 用于 store 关联的稳定 id（基于文件名 + 时间戳） */
  fileId: string;
  fileName: string;
  size: number;
  /** GLB 即 application/octet-stream，glTF 文本为 model/gltf+json，这里只做记录 */
  mimeType: string;
  /** 同一 buffer 会同时喂给 three GLTFLoader（解析） */
  arrayBuffer: ArrayBuffer;
  /** 通过头 4 字节 magic "glTF" 简单识别 */
  isBinaryGlb: boolean;
  /** 是否检测到 Draco 压缩（仅用于 UI 展示，真实解码由 three 内部处理） */
  dracoCompressed: boolean;
}

const GLB_MAGIC = 0x46546c67; // 'glTF'

function readAsArrayBuffer(file: File): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const { result } = reader;
      if (result instanceof ArrayBuffer) {
        resolve(result);
        return;
      }
      reject(new Error('FileReader result is not ArrayBuffer'));
    };
    reader.onerror = () => reject(reader.error ?? new Error('FileReader unknown error'));
    reader.readAsArrayBuffer(file);
  });
}

/**
 * 嗅探 GLB 头部，并对 ArrayBuffer 做 KHR_draco_mesh_compression 文本嗅探。
 * 这里采用最廉价的"文本扫描"方式：对二进制 buffer 取 ascii，把 32KB 子串作为搜索区。
 * 这不是严格判定（极端情况下可能漏检），但对 UI 展示足够。
 */
function inspectBuffer(buffer: ArrayBuffer): { isBinaryGlb: boolean; dracoCompressed: boolean } {
  const view = new DataView(buffer);
  const isBinaryGlb = buffer.byteLength >= 12 && view.getUint32(0, true) === GLB_MAGIC;

  // 仅扫描前 64KB 文本，避免大文件性能问题
  const sampleLength = Math.min(buffer.byteLength, 64 * 1024);
  const sample = new Uint8Array(buffer, 0, sampleLength);
  const target = 'KHR_draco_mesh_compression';
  const dracoCompressed = scanSubstring(sample, target);

  return { isBinaryGlb, dracoCompressed };
}

function scanSubstring(haystack: Uint8Array, needle: string): boolean {
  if (haystack.length < needle.length) {
    return false;
  }
  for (let i = 0; i <= haystack.length - needle.length; i += 1) {
    let matched = true;
    for (let j = 0; j < needle.length; j += 1) {
      if (haystack[i + j] !== needle.charCodeAt(j)) {
        matched = false;
        break;
      }
    }
    if (matched) {
      return true;
    }
  }
  return false;
}

export async function readGltfFile(file: File): Promise<GltfImportResult> {
  const arrayBuffer = await readAsArrayBuffer(file);
  const { isBinaryGlb, dracoCompressed } = inspectBuffer(arrayBuffer);
  const result: GltfImportResult = {
    fileId: `${file.name}::${file.size}::${Date.now()}`,
    fileName: file.name,
    size: file.size,
    mimeType: file.type || (isBinaryGlb ? 'model/gltf-binary' : 'model/gltf+json'),
    arrayBuffer,
    isBinaryGlb,
    dracoCompressed,
  };
  logger.info('gltf-io', 'readGltfFile success', {
    fileName: result.fileName,
    size: result.size,
    isBinaryGlb,
    dracoCompressed,
  });
  return result;
}

export async function readGltfFiles(files: FileList | File[]): Promise<GltfImportResult[]> {
  const list = Array.from(files).filter((file) => /\.(gltf|glb)$/i.test(file.name));
  const out: GltfImportResult[] = [];
  for (const file of list) {
    try {
      out.push(await readGltfFile(file));
    } catch (err) {
      logger.warn('gltf-io', 'readGltfFile failed', { file: file.name, err: String(err) });
    }
  }
  return out;
}
