<template>
  <header class="flex h-12 items-center justify-between border-b border-slate-700 bg-slate-900/95 px-4">
    <div class="flex items-center gap-3">
      <span class="inline-flex h-7 w-7 items-center justify-center rounded-md bg-blue-600 text-xs font-bold">CE</span>
      <div>
        <p class="text-sm font-semibold leading-none text-slate-100">Character Editor</p>
        <p class="mt-1 text-xs leading-none text-slate-400">{{ targetName }}</p>
      </div>
    </div>

    <div class="flex items-center gap-2">
      <input
        id="character-import-files"
        ref="importInputRef"
        class="hidden"
        name="character-import-files"
        type="file"
        accept=".gltf,.glb"
        multiple
        @change="onImportPick"
      />
      <button
        class="rounded-md border border-slate-600 px-3 py-1.5 text-xs hover:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-60"
        :disabled="isImporting"
        type="button"
        @click="triggerImport"
      >
        {{ isImporting ? '导入中…' : '导入' }}
      </button>

      <label class="rounded-md border border-slate-600 px-2 py-1.5 text-xs">
        目标
        <select
          id="topbar-target-file"
          class="ml-1 bg-transparent text-slate-200"
          name="topbar-target-file"
          :value="projectStore.targetFileId ?? ''"
          @change="onTargetChange"
        >
          <option v-for="file in projectStore.files" :key="file.id" class="bg-slate-800" :value="file.id">
            {{ file.name }}
          </option>
        </select>
      </label>

      <label class="rounded-md border border-slate-600 px-2 py-1.5 text-xs">
        Draco
        <select
          id="topbar-draco-preset"
          class="ml-1 bg-transparent text-slate-200"
          name="topbar-draco-preset"
          :value="projectStore.dracoPreset"
          @change="onPresetChange"
        >
          <option class="bg-slate-800" value="none">none</option>
          <option class="bg-slate-800" value="high">high</option>
          <option class="bg-slate-800" value="medium">medium</option>
          <option class="bg-slate-800" value="low">low</option>
          <option class="bg-slate-800" value="custom">custom</option>
        </select>
      </label>

      <button
        class="rounded-md bg-blue-600 px-3 py-1.5 text-xs font-medium hover:bg-blue-500"
        type="button"
        @click="goExport"
      >
        导出
      </button>
    </div>
  </header>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue';
import { useRouter } from 'vue-router';

import { importCharacterFiles } from '../services/file-import';
import { logger } from '../services/logger';
import { useProjectStore } from '../stores/project';

const router = useRouter();
const projectStore = useProjectStore();
const importInputRef = ref<HTMLInputElement | null>(null);
const isImporting = ref(false);

const targetName = computed(() => projectStore.targetFile?.name ?? '未选择目标模型');

function onTargetChange(event: Event) {
  const id = (event.target as HTMLSelectElement).value;
  projectStore.setTarget(id);
  logger.info('top-bar', 'set target model', { id });
}

function onPresetChange(event: Event) {
  const preset = (event.target as HTMLSelectElement).value as 'none' | 'high' | 'medium' | 'low' | 'custom';
  projectStore.setDracoPreset(preset);
  logger.info('top-bar', 'set draco preset', { preset });
}

function triggerImport() {
  if (isImporting.value) {
    return;
  }
  importInputRef.value?.click();
}

async function onImportPick(event: Event) {
  if (isImporting.value) {
    return;
  }

  const input = event.target as HTMLInputElement;
  const { files } = input;
  if (!files?.length) {
    return;
  }

  isImporting.value = true;
  try {
    const importedCount = await importCharacterFiles(files);
    logger.info('top-bar', 'imported files from top bar', { importedCount });
  } finally {
    isImporting.value = false;
    input.value = '';
  }
}

function goExport() {
  router.push('/export');
}
</script>
