import type { AnimMetaFile } from '../types/anim-meta';
import type { ClipEntry, ImportedFile } from '../types/project';
import {
  DEFAULT_DRACO_CUSTOM_OPTIONS,
  buildDracoTransformOptions,
  estimateCompressionRatio,
  normalizeDracoCustomOptions,
  type DracoCustomOptions,
  type DracoMethod,
  type DracoPreset,
  type ExportFormat,
} from './export-config';
import { serializeModelWithDraco } from './gltf-transform-io';
import { logger } from './logger';
import { threePreview } from './three-preview';


interface ExportModelOptions {
  targetFile: ImportedFile;
  clips: ClipEntry[];
  dracoPreset: DracoPreset;
  includeAnimMeta: boolean;
  format: ExportFormat;
  dracoCustomOptions?: Partial<DracoCustomOptions>;
}

interface ExportGlbOptions {
  targetFile: ImportedFile;
  clips: ClipEntry[];
  dracoPreset: DracoPreset;
  includeAnimMeta: boolean;
  dracoCustomOptions?: Partial<DracoCustomOptions>;
}

export interface ExportModelResult {
  artifactBytes: number;
  downloadBytes: number;
  artifactCount: number;
  artifactNames: string[];
  animMetaBytes: number;
}


function stripExtension(fileName: string): string {
  return fileName.replace(/\.[^./\\]+$/, '');
}

function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  URL.revokeObjectURL(url);
}

export {
  DEFAULT_DRACO_CUSTOM_OPTIONS,
  buildDracoTransformOptions,
  estimateCompressionRatio,
  normalizeDracoCustomOptions,
  type DracoCustomOptions,
  type DracoMethod,
  type DracoPreset,
  type ExportFormat,
};

export function buildAnimMetaFile(source: string, clips: ClipEntry[]): AnimMetaFile {
  return {
    source,
    version: '1.0.0',
    clips: clips.map((clip) => ({
      ...clip.meta,
      name: clip.currentName,
    })),
  };
}

export async function exportTargetModel(options: ExportModelOptions): Promise<ExportModelResult> {
  const { targetFile, clips, dracoPreset, includeAnimMeta, format, dracoCustomOptions } = options;
  if (!targetFile.arrayBuffer) {
    throw new Error('目标文件缺少可导出的二进制数据');
  }

  const normalizedCustomOptions = dracoPreset === 'custom' ? normalizeDracoCustomOptions(dracoCustomOptions) : undefined;
  const exportClipNames = clips.map((clip) => clip.currentName);
  const previewMergedBuffer = await threePreview.exportMergedModelBuffer(targetFile.id, exportClipNames);
  const sourceBuffer = previewMergedBuffer ?? targetFile.arrayBuffer;

  if (!previewMergedBuffer) {
    logger.warn('export-bundle', 'export fallback to original target arrayBuffer (preview not ready)', {
      fileId: targetFile.id,
      fileName: targetFile.name,
      expectedClipCount: exportClipNames.length,
    });
  }

  const artifacts = await serializeModelWithDraco({
    fileName: targetFile.name,
    arrayBuffer: sourceBuffer,
    format,
    dracoPreset,
    dracoCustomOptions: normalizedCustomOptions,
  });

  const artifactBytes = artifacts.reduce((sum, artifact) => sum + artifact.bytes.byteLength, 0);
  const artifactNames = artifacts.map((artifact) => artifact.fileName);

  artifacts.forEach((artifact) => {
    const blob = new Blob([Uint8Array.from(artifact.bytes)], { type: artifact.mimeType });
    downloadBlob(blob, artifact.fileName);
  });

  let animMetaBytes = 0;
  if (includeAnimMeta) {
    const animMeta = buildAnimMetaFile(targetFile.name, clips);
    const metaText = JSON.stringify(animMeta, null, 2);
    animMetaBytes = new TextEncoder().encode(metaText).byteLength;
    const metaBlob = new Blob([metaText], { type: 'application/json' });
    const metaFileName = `${stripExtension(targetFile.name)}.anim-meta.json`;
    downloadBlob(metaBlob, metaFileName);
    artifactNames.push(metaFileName);
  }

  const result: ExportModelResult = {
    artifactBytes,
    downloadBytes: artifactBytes + animMetaBytes,
    artifactCount: artifactNames.length,
    artifactNames,
    animMetaBytes,
  };

  logger.info('export-bundle', 'export target model success', {
    fileId: targetFile.id,
    fileName: targetFile.name,
    clipCount: clips.length,
    includeAnimMeta,
    dracoPreset,
    format,
    dracoCustomOptions: normalizedCustomOptions,
    artifactNames,
    artifactBytes,
    downloadBytes: result.downloadBytes,
  });

  return result;
}

export async function exportTargetGlb(options: ExportGlbOptions): Promise<ExportModelResult> {
  return exportTargetModel({
    ...options,
    format: 'glb',
  });
}

