import { defineStore } from 'pinia';

import type { GltfImportResult } from '../services/gltf-io';
import type { ImportedFile } from '../types/project';

type DracoPreset = 'none' | 'high' | 'medium' | 'low' | 'custom';

export const useProjectStore = defineStore('character-project', {
  state: () => ({
    files: [] as ImportedFile[],
    activeFileId: null as string | null,
    targetFileId: null as string | null,
    dracoPreset: 'high' as DracoPreset,
  }),
  getters: {
    activeFile(state): ImportedFile | null {
      return state.files.find((file) => file.id === state.activeFileId) ?? null;
    },
    targetFile(state): ImportedFile | null {
      return state.files.find((file) => file.id === state.targetFileId) ?? null;
    },
  },
  actions: {
    addFile(file: ImportedFile) {
      this.files.push(file);
      if (!this.activeFileId) {
        this.activeFileId = file.id;
      }
    },
    /**
     * 阶段 2：把 gltf-io 解析后的 result 落库为 ImportedFile，并自动设为激活文件。
     * 顶点数 / 关节数等真实统计在 three-preview 加载完成后再回填（暂以 0 占位）。
     */
    addImportedFile(result: GltfImportResult): ImportedFile {
      const file: ImportedFile = {
        id: result.fileId,
        name: result.fileName,
        size: result.size,
        isTarget: this.files.length === 0,
        dracoCompressed: result.dracoCompressed,
        meshVertexCount: 0,
        jointCount: 0,
        animationCount: 0,
        arrayBuffer: result.arrayBuffer,
      };
      this.files.push(file);
      this.activeFileId = file.id;
      if (!this.targetFileId) {
        this.targetFileId = file.id;
      }
      return file;
    },
    removeFile(id: string) {
      this.files = this.files.filter((file) => file.id !== id);
      if (this.activeFileId === id) {
        this.activeFileId = this.files[0]?.id ?? null;
      }
      if (this.targetFileId === id) {
        this.targetFileId = this.files[0]?.id ?? null;
      }
    },
    setTarget(id: string) {
      this.targetFileId = id;
      this.files = this.files.map((file) => ({ ...file, isTarget: file.id === id }));
    },
    setActive(id: string) {
      this.activeFileId = id;
    },
    setDracoPreset(preset: DracoPreset) {
      this.dracoPreset = preset;
    },
    setAnimationCount(fileId: string, count: number) {
      this.files = this.files.map((file) => {
        if (file.id !== fileId) {
          return file;
        }
        return {
          ...file,
          animationCount: count,
        };
      });
    },
    setFileStats(fileId: string, stats: { meshVertexCount: number; jointCount: number; animationCount: number }) {
      this.files = this.files.map((file) => {
        if (file.id !== fileId) {
          return file;
        }
        return {
          ...file,
          meshVertexCount: stats.meshVertexCount,
          jointCount: stats.jointCount,
          animationCount: stats.animationCount,
        };
      });
    },
  },
});
