<template>
  <div class="flex h-full min-h-0 bg-slate-950 p-4">
    <div class="grid w-full min-h-0 grid-cols-[320px_minmax(0,1fr)] gap-4">
      <section class="glass-panel flex min-h-0 flex-col p-4">
        <p class="text-xs font-semibold uppercase tracking-wide text-slate-400">导出配置</p>
        <p class="mt-2 text-xs text-slate-500">目标文件：{{ targetName }}</p>

        <label class="mt-4 space-y-1 text-xs text-slate-300">
          <span>导出格式</span>
          <select
            id="export-format"
            v-model="exportFormat"
            class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
            name="export-format"
          >
            <option class="bg-slate-800" value="glb">GLB（单文件）</option>
            <option class="bg-slate-800" value="gltf">GLTF（json + resources）</option>
          </select>
        </label>

        <label class="mt-3 space-y-1 text-xs text-slate-300">
          <span>Draco 预设</span>
          <select
            id="export-draco-preset"
            class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
            name="export-draco-preset"
            :value="projectStore.dracoPreset"
            @change="onPresetChange"
          >
            <option class="bg-slate-800" value="none">none（不压缩）</option>
            <option class="bg-slate-800" value="high">high</option>
            <option class="bg-slate-800" value="medium">medium</option>
            <option class="bg-slate-800" value="low">low</option>
            <option class="bg-slate-800" value="custom">custom</option>
          </select>
        </label>

        <div
          v-if="projectStore.dracoPreset === 'custom'"
          class="mt-3 rounded-md border border-slate-700 bg-slate-900/70 p-3 text-xs text-slate-300"
        >
          <p class="mb-2 text-slate-400">自定义参数</p>
          <div class="grid grid-cols-2 gap-2">
            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">method</span>
              <select v-model="dracoCustomForm.method" class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1">
                <option class="bg-slate-800" value="edgebreaker">edgebreaker</option>
                <option class="bg-slate-800" value="sequential">sequential</option>
              </select>
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">encodeSpeed (0-10)</span>
              <input
                v-model.number="dracoCustomForm.encodeSpeed"
                class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1"
                type="number"
                min="0"
                max="10"
                step="1"
              />
            </label>

            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">quantizePosition (1-16)</span>
              <input
                v-model.number="dracoCustomForm.quantizePosition"
                class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1"
                type="number"
                min="1"
                max="16"
                step="1"
              />
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">quantizeNormal (1-16)</span>
              <input
                v-model.number="dracoCustomForm.quantizeNormal"
                class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1"
                type="number"
                min="1"
                max="16"
                step="1"
              />
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">quantizeTexcoord (1-16)</span>
              <input
                v-model.number="dracoCustomForm.quantizeTexcoord"
                class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1"
                type="number"
                min="1"
                max="16"
                step="1"
              />
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">quantizeColor (1-16)</span>
              <input
                v-model.number="dracoCustomForm.quantizeColor"
                class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1"
                type="number"
                min="1"
                max="16"
                step="1"
              />
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-500">quantizeGeneric (1-16)</span>
              <input
                v-model.number="dracoCustomForm.quantizeGeneric"
                class="w-full rounded border border-slate-600 bg-slate-800 px-2 py-1"
                type="number"
                min="1"
                max="16"
                step="1"
              />
            </label>
          </div>

          <p v-if="customValidationErrors.length" class="mt-2 text-[11px] text-rose-300">
            {{ customValidationErrors.join('；') }}
          </p>
        </div>

        <label class="mt-3 flex items-center gap-2 text-xs text-slate-300">
          <input
            id="include-anim-meta"
            v-model="includeAnimMeta"
            class="h-3.5 w-3.5 accent-blue-500"
            name="include-anim-meta"
            type="checkbox"
          />
          <span>同时下载 anim-meta.json</span>
        </label>

        <div class="mt-4 rounded-md border border-slate-700 bg-slate-900/70 p-3 text-xs">
          <p class="text-slate-400">估算体积，仅供参考</p>
          <div class="mt-2 space-y-1">
            <p class="text-slate-300">原始：{{ formatBytes(originalBytes) }}</p>
            <p class="text-slate-300">估算导出：{{ formatBytes(estimatedBytes) }}</p>
            <p class="text-slate-500">{{ estimatedRate }}</p>
          </div>
        </div>

        <div
          v-if="lastExportResult"
          class="mt-3 rounded-md border border-emerald-500/50 bg-emerald-500/10 p-3 text-xs text-emerald-100"
        >
          <p class="font-medium">实际导出体积：{{ formatBytes(lastExportResult.artifactBytes) }}</p>
          <p class="mt-1 text-emerald-200/80">
            已生成 {{ lastExportResult.artifactCount }} 个下载文件；模型产物不包含 anim-meta.json。
          </p>
          <p v-if="lastExportResult.animMetaBytes" class="mt-1 text-emerald-200/80">
            含 anim-meta.json 的下载总量：{{ formatBytes(lastExportResult.downloadBytes) }}
          </p>
        </div>

        <p
          v-if="actualExportIsLarger"
          class="mt-3 rounded-md border border-amber-500/60 bg-amber-500/10 px-2 py-1.5 text-xs text-amber-200"
        >
          该模型几何占比较低或已压缩，Draco 可能不减小总体积。
        </p>

        <p v-if="errorMsg" class="mt-3 rounded-md border border-rose-500/60 bg-rose-500/10 px-2 py-1.5 text-xs text-rose-300">
          {{ errorMsg }}
        </p>

        <div class="mt-auto flex gap-2 pt-4">
          <button
            class="flex-1 rounded-md border border-slate-600 px-3 py-2 text-xs text-slate-200 hover:bg-slate-800"
            type="button"
            @click="goBack"
          >
            返回工作台
          </button>
          <button
            class="flex-1 rounded-md bg-blue-600 px-3 py-2 text-xs font-medium text-white hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-60"
            :disabled="isExporting || !canExport || !isCustomFormValid"
            type="button"
            @click="onExport"
          >
            {{ isExporting ? '导出中…' : exportButtonText }}
          </button>
        </div>
      </section>

      <section class="glass-panel min-h-0 p-4">
        <p class="text-xs font-semibold uppercase tracking-wide text-slate-400">anim-meta.json 预览</p>
        <pre class="mt-3 h-[calc(100%-2rem)] overflow-auto rounded-md border border-slate-700 bg-slate-900/80 p-3 text-xs leading-5 text-slate-200">{{ previewJson }}</pre>
      </section>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { useRouter } from 'vue-router';

import {
  DEFAULT_DRACO_CUSTOM_OPTIONS,
  estimateCompressionRatio,
  exportTargetModel,
  normalizeDracoCustomOptions,
  type DracoCustomOptions,
  type DracoPreset,
  type ExportFormat,
  type ExportModelResult,
  buildAnimMetaFile,
} from '../services/export-bundle';
import { logger } from '../services/logger';
import { useClipsStore } from '../stores/clips';
import { useProjectStore } from '../stores/project';

const router = useRouter();
const projectStore = useProjectStore();
const clipsStore = useClipsStore();

const exportFormat = ref<ExportFormat>('glb');
const includeAnimMeta = ref(true);
const isExporting = ref(false);
const errorMsg = ref('');
const lastExportResult = ref<ExportModelResult | null>(null);
const dracoCustomForm = reactive<DracoCustomOptions>({ ...DEFAULT_DRACO_CUSTOM_OPTIONS });

const targetFile = computed(() => projectStore.targetFile);
const targetName = computed(() => targetFile.value?.name ?? '未选择目标模型');
const targetClips = computed(() => {
  const fileId = targetFile.value?.id;
  if (!fileId) {
    return [];
  }
  return clipsStore.clips.filter((clip) => clip.fileId === fileId);
});
const canExport = computed(() => Boolean(targetFile.value?.arrayBuffer));

const metaFile = computed(() => {
  if (!targetFile.value) {
    return null;
  }
  return buildAnimMetaFile(targetFile.value.name, targetClips.value);
});

const previewJson = computed(() => {
  if (!metaFile.value) {
    return JSON.stringify(
      {
        source: 'N/A',
        version: '1.0.0',
        clips: [],
      },
      null,
      2,
    );
  }
  return JSON.stringify(metaFile.value, null, 2);
});

const exportButtonText = computed(() => (exportFormat.value === 'gltf' ? '导出 GLTF' : '导出 GLB'));

function isValidIntegerInRange(value: number, min: number, max: number): boolean {
  return Number.isInteger(value) && value >= min && value <= max;
}

const customValidationErrors = computed(() => {
  if (projectStore.dracoPreset !== 'custom') {
    return [] as string[];
  }

  const errors: string[] = [];
  if (!isValidIntegerInRange(dracoCustomForm.encodeSpeed, 0, 10)) {
    errors.push('encodeSpeed 必须是 0-10 的整数');
  }

  const quantFields: Array<keyof DracoCustomOptions> = [
    'quantizePosition',
    'quantizeNormal',
    'quantizeTexcoord',
    'quantizeColor',
    'quantizeGeneric',
  ];
  for (const field of quantFields) {
    if (!isValidIntegerInRange(dracoCustomForm[field] as number, 1, 16)) {
      errors.push(`${field} 必须是 1-16 的整数`);
    }
  }

  return errors;
});

const isCustomFormValid = computed(() => customValidationErrors.value.length === 0);

const normalizedCustomOptions = computed(() => normalizeDracoCustomOptions(dracoCustomForm));

const originalBytes = computed(() => targetFile.value?.arrayBuffer?.byteLength ?? targetFile.value?.size ?? 0);
const estimatedBytes = computed(() => {
  if (!originalBytes.value) {
    return 0;
  }
  const ratio = estimateCompressionRatio(projectStore.dracoPreset as DracoPreset, normalizedCustomOptions.value);
  return Math.round(originalBytes.value * ratio);
});

const estimatedRate = computed(() => {
  if (!originalBytes.value) {
    return '暂无可估算数据';
  }
  const ratio = Math.round((estimatedBytes.value / originalBytes.value) * 100);
  return `理论估算约为原始文件的 ${ratio}%；实际体积以导出后结果为准`;
});

const actualExportIsLarger = computed(() => {
  if (!lastExportResult.value || !originalBytes.value) {
    return false;
  }
  return lastExportResult.value.artifactBytes > originalBytes.value;
});

watch(
  () => [
    targetFile.value?.id,
    exportFormat.value,
    includeAnimMeta.value,
    projectStore.dracoPreset,
    dracoCustomForm.method,
    dracoCustomForm.quantizePosition,
    dracoCustomForm.quantizeNormal,
    dracoCustomForm.quantizeTexcoord,
    dracoCustomForm.quantizeColor,
    dracoCustomForm.quantizeGeneric,
    dracoCustomForm.encodeSpeed,
  ],
  () => {
    lastExportResult.value = null;
  },
);

function formatBytes(bytes: number): string {
  if (!bytes) {
    return '0 B';
  }
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  if (bytes < 1024 * 1024) {
    return `${(bytes / 1024).toFixed(1)} KB`;
  }
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

function onPresetChange(event: Event) {
  const preset = (event.target as HTMLSelectElement).value as DracoPreset;
  projectStore.setDracoPreset(preset);
}

async function onExport() {
  const target = targetFile.value;
  if (!target?.arrayBuffer) {
    errorMsg.value = '目标文件为空，请先导入并选择目标模型';
    return;
  }

  if (!isCustomFormValid.value) {
    errorMsg.value = '自定义参数不合法，请先修正后再导出';
    return;
  }

  isExporting.value = true;
  errorMsg.value = '';
  lastExportResult.value = null;
  try {
    lastExportResult.value = await exportTargetModel({
      targetFile: target,
      clips: targetClips.value,
      dracoPreset: projectStore.dracoPreset as DracoPreset,
      dracoCustomOptions: projectStore.dracoPreset === 'custom' ? normalizedCustomOptions.value : undefined,
      includeAnimMeta: includeAnimMeta.value,
      format: exportFormat.value,
    });
  } catch (error) {
    errorMsg.value = `导出失败：${String(error)}`;
    logger.warn('export-preview', 'export model failed', { error: String(error), format: exportFormat.value });
  } finally {
    isExporting.value = false;
  }
}

function goBack() {
  router.push('/');
}
</script>
