import type { AnimMeta, Gait } from '../types/anim-meta';

export interface ClipComputeInput {
  name: string;
  duration: number;
  rootDisplacementXZ?: number;
}

interface GaitScalePreset {
  minScale: number;
  maxScale: number;
  defaultScale: number;
}

const IN_PLACE_THRESHOLD = 0.05;

const GAIT_SCALE_PRESET: Record<Gait, GaitScalePreset> = {
  idle: { minScale: 0.8, maxScale: 1.2, defaultScale: 1.0 },
  walk: { minScale: 0.6, maxScale: 1.6, defaultScale: 1.0 },
  run: { minScale: 0.7, maxScale: 1.5, defaultScale: 1.0 },
  jump: { minScale: 0.8, maxScale: 1.2, defaultScale: 1.0 },
  fall: { minScale: 0.8, maxScale: 1.2, defaultScale: 1.0 },
  other: { minScale: 0.5, maxScale: 2.0, defaultScale: 1.0 },
};

function inferLoop(): boolean {
  return true;
}


function inferGait(name: string): Gait {
  if (/idle/i.test(name)) {
    return 'idle';
  }
  if (/walk/i.test(name)) {
    return 'walk';
  }
  if (/run|sprint|jog/i.test(name)) {
    return 'run';
  }
  if (/jump|leap/i.test(name)) {
    return 'jump';
  }
  if (/fall|land/i.test(name)) {
    return 'fall';
  }
  return 'other';
}

function fallbackSpeedByGait(gait: Gait): number {
  if (gait === 'walk') {
    return 1.4;
  }
  if (gait === 'run') {
    return 4.2;
  }
  return 0;
}

function computeAuthoredSpeed(gait: Gait, duration: number, displacementXZ?: number): number {
  if (gait !== 'walk' && gait !== 'run') {
    return 0;
  }

  if (!Number.isFinite(duration) || duration <= 0) {
    return fallbackSpeedByGait(gait);
  }

  if (!Number.isFinite(displacementXZ)) {
    return fallbackSpeedByGait(gait);
  }

  const safeDistance = Math.max(0, displacementXZ ?? 0);
  if (safeDistance < IN_PLACE_THRESHOLD) {
    return fallbackSpeedByGait(gait);
  }

  return safeDistance / duration;
}

export function computeMeta(input: ClipComputeInput): AnimMeta {
  const gait = inferGait(input.name);
  const preset = GAIT_SCALE_PRESET[gait];

  return {
    name: input.name,
    authoredSpeedMps: computeAuthoredSpeed(gait, input.duration, input.rootDisplacementXZ),
    minScale: preset.minScale,
    maxScale: preset.maxScale,
    defaultScale: preset.defaultScale,
    gait,
    loop: inferLoop(),

  };
}

export function computePreviewTimeScale(meta: AnimMeta, previewSpeedMps: number): number {
  const safePreviewSpeed = Number.isFinite(previewSpeedMps) ? Math.max(0, previewSpeedMps) : 0;
  const safeDefaultScale = Number.isFinite(meta.defaultScale) ? Math.max(0.1, Math.min(5, meta.defaultScale)) : 1;

  if (!Number.isFinite(meta.authoredSpeedMps) || meta.authoredSpeedMps <= 0) {
    return safeDefaultScale;
  }

  const rawScale = safePreviewSpeed / meta.authoredSpeedMps;
  const min = Number.isFinite(meta.minScale) ? meta.minScale : 0.5;
  const max = Number.isFinite(meta.maxScale) ? meta.maxScale : 2;
  const clampedScale = Math.min(Math.max(rawScale, min), max);

  return clampedScale * safeDefaultScale;
}
