import type { ClipEntry } from '../types/project';

const CLIP_NAME_PATTERN = /^[A-Za-z0-9_-]+$/;
const MAX_CLIP_NAME_LENGTH = 64;

export interface RenameResult {
  ok: boolean;
  conflict?: string;
  reason?: 'empty' | 'too_long' | 'invalid_chars' | 'not_found';
  nextClips?: ClipEntry[];
}

function sanitizeName(name: string): string {
  return name.trim();
}

function validateName(name: string): RenameResult | null {
  if (!name) {
    return { ok: false, reason: 'empty' };
  }

  if (name.length > MAX_CLIP_NAME_LENGTH) {
    return { ok: false, reason: 'too_long' };
  }

  if (!CLIP_NAME_PATTERN.test(name)) {
    return { ok: false, reason: 'invalid_chars' };
  }

  return null;
}

export function renameClip(clips: ClipEntry[], clipId: string, newName: string): RenameResult {
  const trimmedName = sanitizeName(newName);
  const invalid = validateName(trimmedName);
  if (invalid) {
    return invalid;
  }

  const target = clips.find((clip) => clip.id === clipId);
  if (!target) {
    return { ok: false, reason: 'not_found' };
  }

  const conflict = clips.find(
    (clip) => clip.id !== clipId && clip.fileId === target.fileId && clip.currentName.toLowerCase() === trimmedName.toLowerCase(),
  );
  if (conflict) {
    return { ok: false, conflict: conflict.id };
  }

  const nextClips = clips.map((clip) => {
    if (clip.id !== clipId) {
      return clip;
    }
    return {
      ...clip,
      currentName: trimmedName,
      meta: {
        ...clip.meta,
        name: trimmedName,
      },
    };
  });

  return {
    ok: true,
    nextClips,
  };
}
