const PREFIX = '[character-editor]';

function format(scope: string, message: string): string {
  return `${PREFIX}[${scope}] ${message}`;
}

export const logger = {
  info(scope: string, message: string, payload?: unknown) {
    console.info(format(scope, message), payload ?? '');
  },
  warn(scope: string, message: string, payload?: unknown) {
    console.warn(format(scope, message), payload ?? '');
  },
  error(scope: string, message: string, payload?: unknown) {
    console.error(format(scope, message), payload ?? '');
  },
};
