import { useClipsStore } from '../stores/clips';
import { useProjectStore } from '../stores/project';
import { readGltfFiles } from './gltf-io';
import { logger } from './logger';
import { threePreview } from './three-preview';

export async function importCharacterFiles(fileList: FileList | File[]): Promise<number> {
  const filtered = Array.from(fileList).filter((file) => /\.(gltf|glb)$/i.test(file.name));
  if (!filtered.length) {
    logger.warn('file-import', 'no .gltf/.glb in import list');
    return 0;
  }

  const projectStore = useProjectStore();
  const clipsStore = useClipsStore();
  const results = await readGltfFiles(filtered);

  let importedCount = 0;
  for (const result of results) {
    const file = projectStore.addImportedFile(result);
    try {
      const loadResult = await threePreview.load(result.arrayBuffer, file.id);
      clipsStore.replaceClipsForFile(file.id, loadResult.clips, loadResult.availableMorphTargets);
      projectStore.setFileStats(file.id, loadResult.stats);
      importedCount += 1;
    } catch (err) {
      logger.warn('file-import', 'three-preview load failed', { err: String(err), file: file.name });
    }
  }

  return importedCount;
}
