<template>
  <footer
    class="flex h-7 items-center justify-between border-t border-slate-700 bg-slate-900 px-3 font-mono text-xs text-slate-400"
  >
    <div class="flex items-center gap-4">
      <span>FPS {{ fps }}</span>
      <span>Verts {{ activeVertices }}</span>
      <span>Clips {{ clipCount }}</span>
    </div>
    <span class="truncate text-right text-slate-500">{{ latestLog }}</span>
  </footer>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue';

import { useClipsStore } from '../stores/clips';
import { useProjectStore } from '../stores/project';

const projectStore = useProjectStore();
const clipsStore = useClipsStore();
const fps = ref(60);

const timer = window.setInterval(() => {
  fps.value = 56 + Math.round(Math.random() * 6);
}, 1200);

onBeforeUnmount(() => {
  window.clearInterval(timer);
});

const activeVertices = computed(() => projectStore.activeFile?.meshVertexCount ?? 0);
const clipCount = computed(() => clipsStore.clips.length);
const latestLog = computed(() =>
  clipsStore.selectedClip ? `Selected ${clipsStore.selectedClip.currentName}` : 'Ready',
);
</script>
