<template>
  <div class="relative h-full overflow-hidden rounded-xl border border-slate-700 bg-slate-900">
    <canvas ref="canvasRef" class="absolute inset-0 h-full w-full" />

    <Transition name="fade" mode="out-in">
      <div
        v-if="!hasLoadedFile"
        class="pointer-events-none absolute inset-0 flex items-center justify-center text-slate-300"
      >
        <div class="text-center">
          <p class="text-xs uppercase tracking-wide text-slate-500">Preview</p>
          <p class="mt-2 text-lg font-semibold text-slate-100">{{ selectedName }}</p>
          <p class="mt-1 text-xs text-slate-400">拖入 .glb/.gltf 或点击左侧"选择文件导入"</p>
        </div>
      </div>
    </Transition>

    <div class="absolute right-4 top-4 flex w-72 flex-col gap-3 text-xs text-slate-100">
      <div class="glass-panel px-3 py-3">
      <div class="flex items-center justify-between">
        <p class="text-[11px] font-semibold uppercase tracking-wide text-slate-300">人物照明</p>
        <button
          data-testid="lighting-panel-toggle"
          class="rounded border border-slate-600 px-2 py-1 text-[11px] text-slate-300 hover:bg-slate-800"
          type="button"
          @click="isLightingPanelCollapsed = !isLightingPanelCollapsed"
        >
          {{ isLightingPanelCollapsed ? '展开' : '收起' }}
        </button>
      </div>

      <div v-if="!isLightingPanelCollapsed" class="mt-3 space-y-3">
        <div class="space-y-2 rounded-md border border-slate-700/70 bg-slate-900/70 p-2.5">
          <div class="flex items-center justify-between gap-2">
            <p class="text-[11px] font-medium text-slate-300">基础打光</p>
            <input
              data-testid="base-lighting-enabled-toggle"
              class="h-4 w-4 accent-blue-500"
              type="checkbox"
              :checked="lightingSettings.base.enabled"
              @change="onBaseLightingEnabledChange"
            />
          </div>

          <label class="block space-y-1">
            <span class="text-slate-400">基础打光预设</span>
            <select
              data-testid="lighting-preset-select"
              class="w-full rounded-md border border-slate-600 bg-slate-800 px-2 py-1.5 text-xs"
              :value="lightingSettings.preset"
              @change="onLightingPresetChange"
            >
              <option
                v-for="option in LIGHTING_PRESET_OPTIONS"
                :key="option.value"
                class="bg-slate-800"
                :value="option.value"
              >
                {{ option.label }}
              </option>
            </select>
          </label>

          <label class="flex items-center justify-between gap-2 text-[11px] text-slate-300">
            <span>显示灯位标记</span>
            <input
              data-testid="light-markers-toggle"
              class="h-4 w-4 accent-blue-500"
              type="checkbox"
              :checked="lightingSettings.base.showMarkers"
              @change="onLightMarkersChange"
            />
          </label>
          <p class="text-[11px] text-slate-500">场景里会用同色圆点标识 Key / Fill / Rim 灯位。</p>

          <div class="grid grid-cols-3 gap-2">
            <label class="space-y-1">
              <span class="text-[11px] text-slate-400">Key</span>
              <input
                data-testid="key-light-color-input"
                type="color"
                :value="lightingSettings.base.colors.key"
                @input="onBaseColorInput('key', $event)"
              />
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-400">Fill</span>
              <input
                data-testid="fill-light-color-input"
                type="color"
                :value="lightingSettings.base.colors.fill"
                @input="onBaseColorInput('fill', $event)"
              />
            </label>
            <label class="space-y-1">
              <span class="text-[11px] text-slate-400">Rim</span>
              <input
                data-testid="rim-light-color-input"
                type="color"
                :value="lightingSettings.base.colors.rim"
                @input="onBaseColorInput('rim', $event)"
              />
            </label>
          </div>
        </div>

        <div class="space-y-2 rounded-md border border-slate-700/70 bg-slate-900/70 p-2.5">
          <div class="flex items-center justify-between gap-2">
            <p class="text-[11px] font-medium text-slate-300">漫反射光</p>
            <input
              data-testid="ambient-enabled-toggle"
              class="h-4 w-4 accent-blue-500"
              type="checkbox"
              :checked="lightingSettings.global.ambientEnabled"
              @change="onAmbientEnabledChange"
            />
          </div>

          <div class="grid grid-cols-[auto,1fr] items-end gap-3">
            <label class="space-y-1">
              <span class="text-[11px] text-slate-400">颜色</span>
              <input
                data-testid="ambient-color-input"
                type="color"
                :value="lightingSettings.global.ambientColor"
                @input="onAmbientColorInput"
              />
            </label>
            <label class="space-y-1">
              <div class="flex items-center justify-between text-[11px] text-slate-400">
                <span>强度</span>
                <span>{{ lightingSettings.global.ambientIntensity.toFixed(2) }}</span>
              </div>
              <input
                data-testid="ambient-intensity-slider"
                class="h-1 w-full cursor-pointer accent-blue-500"
                type="range"
                min="0"
                max="1"
                step="0.01"
                :value="lightingSettings.global.ambientIntensity"
                @input="onAmbientIntensityInput"
              />
            </label>
          </div>
        </div>

        <div class="space-y-2 rounded-md border border-slate-700/70 bg-slate-900/70 p-2.5">
          <div class="flex items-center justify-between gap-2">
            <p class="text-[11px] font-medium text-slate-300">HDRI 环境光</p>
            <input
              data-testid="hdri-enabled-toggle"
              class="h-4 w-4 accent-blue-500"
              type="checkbox"
              :checked="lightingSettings.global.hdriEnabled"
              :disabled="!hasHdriFile"
              @change="onHdriEnabledChange"
            />
          </div>

          <div class="space-y-2 rounded-md border border-slate-700 bg-slate-900/70 p-2">
            <p class="text-[11px] text-slate-400">先上传 HDRI 文件后才能开启环境光，支持 `.hdr` 与常规全景图。</p>
            <p class="truncate text-[11px] text-slate-500">{{ hdriFileName || '未上传 HDRI 文件' }}</p>
            <div class="flex items-center gap-1.5">
              <button
                data-testid="hdri-upload-btn"
                class="rounded border border-slate-600 px-2 py-1 text-[11px] text-slate-300 hover:bg-slate-800"
                type="button"
                @click="openHdriPicker"
              >
                上传 HDRI
              </button>
              <button
                v-if="hasHdriFile"
                data-testid="hdri-clear-btn"
                class="rounded border border-slate-600 px-2 py-1 text-[11px] text-slate-300 hover:bg-slate-800"
                type="button"
                @click="clearHdri"
              >
                清空
              </button>
            </div>
            <input
              ref="hdriFileInputRef"
              class="hidden"
              type="file"
              accept=".hdr,image/*"
              @change="onHdriFileChange"
            />
          </div>

          <label class="flex items-center justify-between gap-2 text-[11px] text-slate-300">
            <span>显示 HDRI 背景</span>
            <input
              data-testid="hdri-background-toggle"
              class="h-4 w-4 accent-blue-500"
              type="checkbox"
              :checked="lightingSettings.global.hdriShowBackground"
              :disabled="!hasHdriFile || !lightingSettings.global.hdriEnabled"
              @change="onHdriBackgroundChange"
            />
          </label>

          <label class="space-y-1" :class="lightingSettings.global.hdriEnabled ? '' : 'opacity-50'">
            <div class="flex items-center justify-between text-[11px] text-slate-400">
              <span>HDRI 强度</span>
              <span>{{ lightingSettings.global.hdriIntensity.toFixed(2) }}</span>
            </div>
            <input
              data-testid="hdri-intensity-slider"
              class="h-1 w-full cursor-pointer accent-blue-500"
              type="range"
              min="0"
              max="2"
              step="0.01"
              :value="lightingSettings.global.hdriIntensity"
              :disabled="!lightingSettings.global.hdriEnabled"
              @input="onHdriIntensityInput"
            />
          </label>
        </div>
      </div>
    </div>

      <div class="glass-panel px-3 py-3">
        <div class="flex items-center justify-between gap-2">
          <p class="text-[11px] font-semibold uppercase tracking-wide text-slate-300">摄像机</p>
          <button
            data-testid="camera-panel-toggle"
            class="rounded border border-slate-600 px-2 py-1 text-[11px] text-slate-300 hover:bg-slate-800"
            type="button"
            @click="isCameraPanelCollapsed = !isCameraPanelCollapsed"
          >
            {{ isCameraPanelCollapsed ? '展开' : '收起' }}
          </button>
        </div>

        <div v-if="!isCameraPanelCollapsed" class="mt-3 space-y-2 rounded-md border border-slate-700/70 bg-slate-900/70 p-2.5">
          <div class="flex items-center justify-between text-[11px] text-slate-400">
            <span>视野角</span>
            <span>{{ cameraFov.toFixed(0) }}°</span>
          </div>
          <input
            data-testid="camera-fov-slider"
            class="h-1 w-full cursor-pointer accent-blue-500"
            type="range"
            :min="MIN_CAMERA_FOV"
            :max="MAX_CAMERA_FOV"
            step="1"
            :value="cameraFov"
            @input="onCameraFovInput"
          />
          <p class="text-[11px] text-slate-500">支持 20°-180° 调节；数值越小越接近中焦，越大则广角透视更明显。</p>
        </div>
      </div>
    </div>

    <div
      class="glass-panel absolute bottom-4 left-1/2 flex -translate-x-1/2 items-center gap-3 px-3 py-2 text-xs text-slate-200"
    >
      <button
        class="rounded px-2 py-1"
        :class="isPlaying ? 'bg-slate-700 hover:bg-slate-600' : 'bg-blue-600 hover:bg-blue-500'"
        :disabled="!playbackClipName"
        type="button"
        @click="togglePlay"
      >
        {{ isPlaying ? '⏸' : '▶' }}
      </button>
      <span class="text-slate-400">速率</span>
      <input
        v-model.number="timeScale"
        class="h-1 w-24 cursor-pointer accent-blue-500"
        type="range"
        min="0.1"
        max="3"
        step="0.05"
        :disabled="!playbackClipName"
        @input="onTimeScaleInput"
      />
      <span class="w-10 tabular-nums text-slate-200">{{ timeScale.toFixed(2) }}x</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';

import { logger } from '../services/logger';
import {
  createDefaultPreviewLightingSettings,
  DEFAULT_CAMERA_FOV,
  LIGHTING_PRESET_OPTIONS,
  MAX_CAMERA_FOV,
  MIN_CAMERA_FOV,
  threePreview,
  type LightingPreset,
  type PreviewLightingSettings,
} from '../services/three-preview';
import { useClipsStore } from '../stores/clips';
import { useProjectStore } from '../stores/project';

const canvasRef = ref<HTMLCanvasElement | null>(null);
const hdriFileInputRef = ref<HTMLInputElement | null>(null);
const projectStore = useProjectStore();
const clipsStore = useClipsStore();

const isPlaying = ref(false);
const timeScale = ref(1);
const cameraFov = ref(DEFAULT_CAMERA_FOV);
const lightingSettings = reactive(createDefaultPreviewLightingSettings());
const isLightingPanelCollapsed = ref(false);
const isCameraPanelCollapsed = ref(false);
const hasHdriFile = ref(false);
const hdriFileName = ref('');

const selectedClipName = computed(() => clipsStore.selectedClip?.currentName ?? null);
const playbackClipName = computed(
  () => clipsStore.selectedClip?.currentName ?? clipsStore.selectedClip?.originalName ?? null,
);
const selectedName = computed(() => selectedClipName.value ?? '未选中动画');
const hasLoadedFile = computed(() =>
  projectStore.files.some((file) => Boolean(file.arrayBuffer)),
);

onMounted(() => {
  if (!canvasRef.value) {
    return;
  }
  threePreview.mount(canvasRef.value);
  ensureActiveLoaded();
});

onBeforeUnmount(() => {
  threePreview.unmount();
});

watch(
  () => projectStore.activeFileId,
  () => {
    ensureActiveLoaded();
  },
);

watch(
  () => clipsStore.selectedClipId,
  (nextId, prevId) => {
    logger.info('preview-canvas', 'selected clip changed', {
      prevId,
      nextId,
      activeFileId: projectStore.activeFileId,
      playbackClipName: playbackClipName.value,
    });
    playSelectedClip();
  },
  { immediate: true },
);

watch(
  () => clipsStore.selectedClip?.morphValidation,
  (validation) => {
    if (!validation) {
      threePreview.resetMorphWeights();
      return;
    }
    const weights = Object.fromEntries(validation.channels.map((item) => [item.channel, item.weight]));
    threePreview.setMorphWeights(weights);
  },
  { deep: true, immediate: true },
);

watch(
  () => clipsStore.selectedClip?.meta.loop,
  (loop) => {
    if (typeof loop !== 'boolean') {
      return;
    }
    if (clipsStore.selectedClip?.fileId !== projectStore.activeFileId) {
      return;
    }
    threePreview.setLoop(loop);
  },
);

watch(
  lightingSettings,
  () => {
    if (!hasHdriFile.value) {
      if (lightingSettings.global.hdriEnabled) {
        lightingSettings.global.hdriEnabled = false;
        return;
      }
      if (lightingSettings.global.hdriShowBackground) {
        lightingSettings.global.hdriShowBackground = false;
        return;
      }
    }

    if (!lightingSettings.global.hdriEnabled && lightingSettings.global.hdriShowBackground) {
      lightingSettings.global.hdriShowBackground = false;
      return;
    }

    threePreview.setLightingSettings(lightingSettings);
  },
  { deep: true, immediate: true },
);

watch(
  cameraFov,
  () => {
    threePreview.setCameraFov(cameraFov.value);
  },
  { immediate: true },
);

function ensureActiveLoaded() {
  const file = projectStore.activeFile;
  if (!file?.arrayBuffer) {
    return;
  }
  threePreview
    .load(file.arrayBuffer, file.id)
    .then((loadResult) => {
      const hasAny = clipsStore.clips.some((clip) => clip.fileId === file.id);
      if (!hasAny) {
        clipsStore.replaceClipsForFile(file.id, loadResult.clips, loadResult.availableMorphTargets);
      }
      projectStore.setFileStats(file.id, loadResult.stats);
      playSelectedClip();
    })
    .catch((err) => logger.warn('preview-canvas', 'load failed', { err: String(err) }));
}

function playSelectedClip() {
  const name = playbackClipName.value;
  if (!name) {
    logger.info('preview-canvas', 'skip playSelectedClip: empty playback name', {
      selectedClipId: clipsStore.selectedClipId,
    });
    isPlaying.value = false;
    return;
  }

  const { selectedClip } = clipsStore;
  if (selectedClip?.fileId !== projectStore.activeFileId) {
    logger.info('preview-canvas', 'skip playSelectedClip: selected clip/file mismatch', {
      selectedClipId: clipsStore.selectedClipId,
      selectedClipFileId: selectedClip?.fileId,
      activeFileId: projectStore.activeFileId,
      playbackClipName: name,
    });
    isPlaying.value = false;
    return;
  }

  const loop = selectedClip.meta.loop ?? true;
  logger.info('preview-canvas', 'playSelectedClip', {
    selectedClipId: selectedClip.id,
    playbackClipName: name,
    loop,
    timeScale: timeScale.value,
  });
  threePreview.playClip(name, { loop, timeScale: timeScale.value });
  isPlaying.value = true;
}

function togglePlay() {
  if (!playbackClipName.value) {
    return;
  }
  if (isPlaying.value) {
    threePreview.pause();
    isPlaying.value = false;
  } else {
    playSelectedClip();
  }
}

function onTimeScaleInput() {
  threePreview.setTimeScale(timeScale.value);
}

function onCameraFovInput(event: Event) {
  const value = Number((event.target as HTMLInputElement).value);
  if (Number.isNaN(value)) {
    return;
  }
  cameraFov.value = Math.min(MAX_CAMERA_FOV, Math.max(MIN_CAMERA_FOV, value));
}

function onLightingPresetChange(event: Event) {
  lightingSettings.preset = (event.target as HTMLSelectElement).value as LightingPreset;
}

function onBaseLightingEnabledChange(event: Event) {
  lightingSettings.base.enabled = (event.target as HTMLInputElement).checked;
}

function onLightMarkersChange(event: Event) {
  lightingSettings.base.showMarkers = (event.target as HTMLInputElement).checked;
}

function onBaseColorInput(key: keyof PreviewLightingSettings['base']['colors'], event: Event) {
  const { value } = event.target as HTMLInputElement;
  lightingSettings.base.colors[key] = value;
}

function onAmbientEnabledChange(event: Event) {
  lightingSettings.global.ambientEnabled = (event.target as HTMLInputElement).checked;
}

function onAmbientColorInput(event: Event) {
  const { value } = event.target as HTMLInputElement;
  lightingSettings.global.ambientColor = value;
}

function onAmbientIntensityInput(event: Event) {
  const value = Number((event.target as HTMLInputElement).value);
  if (Number.isNaN(value)) {
    return;
  }
  lightingSettings.global.ambientIntensity = Math.min(1, Math.max(0, value));
}

function onHdriEnabledChange(event: Event) {
  const { checked } = event.target as HTMLInputElement;
  lightingSettings.global.hdriEnabled = hasHdriFile.value ? checked : false;
}

function onHdriBackgroundChange(event: Event) {
  const { checked } = event.target as HTMLInputElement;
  lightingSettings.global.hdriShowBackground = hasHdriFile.value && lightingSettings.global.hdriEnabled ? checked : false;
}

function onHdriIntensityInput(event: Event) {
  const value = Number((event.target as HTMLInputElement).value);
  if (Number.isNaN(value)) {
    return;
  }
  lightingSettings.global.hdriIntensity = Math.min(2, Math.max(0, value));
}

function openHdriPicker() {
  hdriFileInputRef.value?.click();
}

async function onHdriFileChange(event: Event) {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0] ?? null;
  if (!file) {
    return;
  }

  const loaded = await threePreview.setHdriTextureFile(file);
  if (!loaded) {
    logger.warn('preview-canvas', 'hdri file rejected', { name: file.name });
    hasHdriFile.value = false;
    hdriFileName.value = '';
    lightingSettings.global.hdriEnabled = false;
    lightingSettings.global.hdriShowBackground = false;
    input.value = '';
    return;
  }

  hasHdriFile.value = true;
  hdriFileName.value = file.name;
  lightingSettings.global.hdriEnabled = true;
}

async function clearHdri() {
  await threePreview.setHdriTextureFile(null);
  hasHdriFile.value = false;
  hdriFileName.value = '';
  lightingSettings.global.hdriEnabled = false;
  lightingSettings.global.hdriShowBackground = false;
  if (hdriFileInputRef.value) {
    hdriFileInputRef.value.value = '';
  }
}
</script>

<style scoped>
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
</style>
