import type { DracoOptions } from '@gltf-transform/functions';

export type DracoPreset = 'none' | 'high' | 'medium' | 'low' | 'custom';
export type ExportFormat = 'glb' | 'gltf';
export type DracoMethod = 'edgebreaker' | 'sequential';

export interface DracoCustomOptions {
  method: DracoMethod;
  quantizePosition: number;
  quantizeNormal: number;
  quantizeTexcoord: number;
  quantizeColor: number;
  quantizeGeneric: number;
  encodeSpeed: number;
}

export const DEFAULT_DRACO_CUSTOM_OPTIONS: DracoCustomOptions = {
  method: 'edgebreaker',
  quantizePosition: 14,
  quantizeNormal: 10,
  quantizeTexcoord: 12,
  quantizeColor: 8,
  quantizeGeneric: 12,
  encodeSpeed: 5,
};

function clampInt(value: number, min: number, max: number): number {
  const safeValue = Number.isFinite(value) ? Math.round(value) : min;
  return Math.min(max, Math.max(min, safeValue));
}

export function normalizeDracoCustomOptions(input?: Partial<DracoCustomOptions>): DracoCustomOptions {
  const source = input ?? DEFAULT_DRACO_CUSTOM_OPTIONS;
  return {
    method: source.method === 'sequential' ? 'sequential' : 'edgebreaker',
    quantizePosition: clampInt(source.quantizePosition ?? DEFAULT_DRACO_CUSTOM_OPTIONS.quantizePosition, 1, 16),
    quantizeNormal: clampInt(source.quantizeNormal ?? DEFAULT_DRACO_CUSTOM_OPTIONS.quantizeNormal, 1, 16),
    quantizeTexcoord: clampInt(source.quantizeTexcoord ?? DEFAULT_DRACO_CUSTOM_OPTIONS.quantizeTexcoord, 1, 16),
    quantizeColor: clampInt(source.quantizeColor ?? DEFAULT_DRACO_CUSTOM_OPTIONS.quantizeColor, 1, 16),
    quantizeGeneric: clampInt(source.quantizeGeneric ?? DEFAULT_DRACO_CUSTOM_OPTIONS.quantizeGeneric, 1, 16),
    encodeSpeed: clampInt(source.encodeSpeed ?? DEFAULT_DRACO_CUSTOM_OPTIONS.encodeSpeed, 0, 10),
  };
}

export function estimateCompressionRatio(preset: DracoPreset, customOptions?: Partial<DracoCustomOptions>): number {
  if (preset === 'none') {
    return 1;
  }
  if (preset === 'high') {
    return 0.72;
  }
  if (preset === 'medium') {
    return 0.58;
  }
  if (preset === 'low') {
    return 0.45;
  }

  const options = normalizeDracoCustomOptions(customOptions);
  const quantSum =
    options.quantizePosition +
    options.quantizeNormal +
    options.quantizeTexcoord +
    options.quantizeColor +
    options.quantizeGeneric;
  const quantAvg = quantSum / 5;

  const quantFactor = 0.38 + (quantAvg / 16) * 0.42;
  const speedFactor = 0.08 * (options.encodeSpeed / 10);
  const methodFactor = options.method === 'sequential' ? 0.03 : 0;

  const ratio = quantFactor + speedFactor + methodFactor;
  return Math.min(0.92, Math.max(0.35, Number(ratio.toFixed(3))));
}

export function buildDracoTransformOptions(
  preset: DracoPreset,
  customOptions?: Partial<DracoCustomOptions>,
): DracoOptions | null {
  if (preset === 'none') {
    return null;
  }

  if (preset === 'high') {
    return {
      method: 'edgebreaker',
      quantizePosition: 16,
      quantizeNormal: 12,
      quantizeTexcoord: 14,
      quantizeColor: 10,
      quantizeGeneric: 14,
      encodeSpeed: 0,
      decodeSpeed: 5,
      quantizationVolume: 'mesh',
    };
  }

  if (preset === 'medium') {
    return {
      method: 'edgebreaker',
      quantizePosition: 14,
      quantizeNormal: 10,
      quantizeTexcoord: 12,
      quantizeColor: 8,
      quantizeGeneric: 12,
      encodeSpeed: 5,
      decodeSpeed: 5,
      quantizationVolume: 'mesh',
    };
  }

  if (preset === 'low') {
    return {
      method: 'edgebreaker',
      quantizePosition: 11,
      quantizeNormal: 8,
      quantizeTexcoord: 10,
      quantizeColor: 6,
      quantizeGeneric: 10,
      encodeSpeed: 10,
      decodeSpeed: 5,
      quantizationVolume: 'mesh',
    };
  }

  const normalized = normalizeDracoCustomOptions(customOptions);
  return {
    method: normalized.method,
    quantizePosition: normalized.quantizePosition,
    quantizeNormal: normalized.quantizeNormal,
    quantizeTexcoord: normalized.quantizeTexcoord,
    quantizeColor: normalized.quantizeColor,
    quantizeGeneric: normalized.quantizeGeneric,
    encodeSpeed: normalized.encodeSpeed,
    decodeSpeed: 5,
    quantizationVolume: 'mesh',
  };
}
